  static _authRedirecting = false;

  // V3 模型接口使用 sk- 开头的 API Key。仅在内存中缓存，避免把密钥写进画布快照。
  static _v3ApiKeyCache = { ownerToken: null, key: null };

  static resetV3ApiKeyCache() {
    ApiService._v3ApiKeyCache = { ownerToken: null, key: null };
  }

  _handleAuthExpired() {
    if (ApiService._authRedirecting) return;
    ApiService._authRedirecting = true;
    LocalDataService.set_user_data(null);
    toast.info('登录已过期，请重新登录');
    setTimeout(() => {
      const redirectPath = window.location.hash.replace('#', '') || '/';
      window.dispatchEvent(new CustomEvent('canvas:auth-required', {
        detail: { redirectPath }
      }));
      ApiService._authRedirecting = false;
    }, 1000);
  }

  _isAuthError(error) {
    if (error.status === 401) return true;
    if (error.status === 500 && error.data) {
      try {
        const raw = typeof error.data === 'string' ? error.data : JSON.stringify(error.data);
        if (raw.includes('过期') && raw.includes('重新登')) return true;
      } catch (_) {}
    }
    return false;
  }

  // 通用的请求方法
  async request (url, method, data, options = {}) {
    const silent = Boolean(options && options.silent);
    const requestOptions = {
      method: method,
      headers: {
        'Content-Type': 'application/json',
        'accept': 'application/json'
      }
    };

    // GET 和 HEAD 请求不能包含 body
    if (method.toUpperCase() !== 'GET' && method.toUpperCase() !== 'HEAD') {
      requestOptions.body = JSON.stringify(data);
    }

    try {
      const response = await fetch(url, requestOptions);
      const responseData = await response.json();
      if (!response.ok) {
        throw { status: response.status, data: JSON.stringify(responseData) };
      }
      return responseData; // 返回解析后的JSON对象
    } catch (error) {
      // console.error(`There was an error with the request to ${url}:`, error);
      // console.log(error,'error');
      
      // 处理网络错误（如 CORS、网络断开等）
      if (!error.status) {
        // 网络错误，没有 status 属性
        const errorMessage = error.message || '网络请求失败';
        if (!silent && url.indexOf('get_open_cmd_list') == -1) {
          toast.error(`网络错误：${errorMessage}。请检查网络连接或稍后重试。`);
        }
        throw error;
      }
      
      if (this._isAuthError(error)) {
        if (!silent) {
          this._handleAuthExpired();
        }
        throw error;
      }
      
      if (!silent && url.indexOf('get_open_cmd_list') == -1) {
        // 403 错误通常是权限或会员限制，由调用方处理，不在这里显示 toast
        if (error.status !== 403) {
          toast.error(`错误：${JSON.stringify(error)}`)
        }
      }
      throw error; // 将错误抛出，使得调用者能够处理它
    }
  }

  // GET 请求方法（带可选 token）
  // url 应该是完整路径如 /api/v3/skills/list
  async get(url, params = {}, token = '') {
    const queryString = Object.entries(params)
      .filter(([_, v]) => v !== null && v !== undefined)
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
      .join('&');
    
    const baseUrl = this.apiBase.replace(/\/api$/, '');
    const fullUrl = queryString ? `${baseUrl}${url}?${queryString}` : `${baseUrl}${url}`;
    
    const requestOptions = {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'accept': 'application/json'
      }
    };
    
    const userData = LocalDataService.load_user_data();
    const authToken = token || userData?.token;
    if (authToken) {
      requestOptions.headers['Authorization'] = `Bearer ${authToken}`;
    }
    
    try {
      const response = await fetch(fullUrl, requestOptions);
      const responseData = await response.json();
      if (!response.ok) {
        throw { status: response.status, data: responseData };
      }
      return responseData;
    } catch (error) {
      if (this._isAuthError(error)) {
        this._handleAuthExpired();
        throw error;
      }
      if (!error.status) {
        const errorMessage = error.message || '网络请求失败';
        toast.error(`网络错误：${errorMessage}`);
      }
      throw error;
    }
  }

