  // DELETE 请求方法（带 token）
  async delete(url) {
    const baseUrl = this.apiBase.replace(/\/api$/, '');
    const fullUrl = `${baseUrl}${url}`;
    
    const requestOptions = {
      method: 'DELETE',
      headers: {
        'Content-Type': 'application/json',
        'accept': 'application/json'
      }
    };
    
    const userData = LocalDataService.load_user_data();
    if (userData?.token) {
      requestOptions.headers['Authorization'] = `Bearer ${userData.token}`;
    }
    
    try {
      const response = await fetch(fullUrl, requestOptions);
      if (response.status === 204) {
        return { success: true };
      }
      const responseData = await response.json();
      if (!response.ok) {
        throw { status: response.status, data: responseData };
      }
      return responseData;
    } catch (error) {
      if (this._isAuthError(error)) {
        this._handleAuthExpired();
        throw error;
      }
      if (!error.status) {
        const errorMessage = error.message || '网络请求失败';
        toast.error(`网络错误：${errorMessage}`);
      }
      throw error;
    }
  }

  // 带 token 的请求方法
  async requestWithToken (url, method, data) {
    const userData = LocalDataService.load_user_data();
    const token = userData?.token;
    
    if (!token) {
      throw new Error('请先登录');
    }

    const requestOptions = {
      method: method,
      headers: {
        'Content-Type': 'application/json',
        'accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    };

    // GET 和 HEAD 请求不能包含 body
    if (method.toUpperCase() !== 'GET' && method.toUpperCase() !== 'HEAD') {
      requestOptions.body = JSON.stringify(data);
    }

    try {
      const response = await fetch(url, requestOptions);
      
      // 对于 DELETE 请求返回 204 No Content，直接返回成功
      if (response.status === 204) {
        return { success: true };
      }

      const responseData = await response.json();
      if (!response.ok) {
        throw { status: response.status, data: responseData };
      }
      return responseData;
    } catch (error) {
      // 处理网络错误（如 CORS、网络断开等）
      if (!error.status) {
        // 网络错误，没有 status 属性
        const errorMessage = error.message || '网络请求失败';
        toast.error(`网络错误：${errorMessage}。请检查网络连接或稍后重试。`);
        throw error;
      }
      
      if (this._isAuthError(error)) {
        this._handleAuthExpired();
      }
      throw error;
    }
  }

  async getV3ApiKey(forceRefresh = false) {
    const userData = LocalDataService.load_user_data();
    const token = userData?.token;

    if (!token) {
      throw new Error('请先登录');
    }

    const cached = ApiService._v3ApiKeyCache;
    if (!forceRefresh && cached.ownerToken === token && cached.key) {
      return cached.key;
    }

    const response = await this.requestWithToken(
      `${this.apiBase}/v3/apikeys/list`,
      'POST',
      { status: 'active', page: 1, page_size: 20 }
    );
    const apiKey = response?.data?.items?.find(item => item.status === 'active' && item.key)?.key;

    if (!apiKey) {
      throw new Error('未找到可用的 API Key，请前往 API Key 管理页检查');
    }

    ApiService._v3ApiKeyCache = { ownerToken: token, key: apiKey };
    return apiKey;
  }

  _getV3ErrorMessage(responseData, fallback) {
    const detail = responseData?.detail;
    if (typeof detail === 'string') return detail;
    if (detail?.message) return detail.message;
    if (typeof responseData?.message === 'string') return responseData.message;
    return fallback;
  }

  async _requestV3(path, method, data, retryOnUnauthorized = true) {
    const apiKey = await this.getV3ApiKey();
    const response = await fetch(`${this.apiBase}${path}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        'accept': 'application/json',
        'Authorization': `Bearer ${apiKey}`,
      },
      body: method === 'GET' || method === 'HEAD' ? undefined : JSON.stringify(data),
    });
    const responseData = await response.json();

    if (!response.ok) {
      if (response.status === 401 && retryOnUnauthorized) {
        ApiService.resetV3ApiKeyCache();
        await this.getV3ApiKey(true);
        return this._requestV3(path, method, data, false);
      }
      const error = new Error(this._getV3ErrorMessage(responseData, 'V3 模型请求失败'));
      error.status = response.status;
      error.data = responseData;
      throw error;
    }

    if (responseData?.code !== undefined && responseData.code !== 200) {
      throw new Error(this._getV3ErrorMessage(responseData, 'V3 模型请求失败'));
    }
    return responseData;
  }

