  // 上传图片到coze（这个方法需要特殊处理，因为是multipart/form-data）
  async upload_image_to_coze (file, uploadToken) {
    const formData = new FormData();
    formData.append('file', file);

    const requestOptions = {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${uploadToken}`,
        'accept': 'application/json'
        // 注意：不要设置 Content-Type，让浏览器自动设置 multipart/form-data 边界
      },
      body: formData
    };

    console.log('准备上传图片到coze:', {
      url: 'https://api.coze.cn/v1/files/upload',
      fileName: file.name,
      fileSize: file.size,
      fileType: file.type,
      tokenPrefix: uploadToken.substring(0, 20) + '...'
    });

    try {
      const response = await fetch('https://api.coze.cn/v1/files/upload', requestOptions);
      
      console.log('Coze上传响应状态:', response.status, response.statusText);
      console.log('Coze上传响应头:', Object.fromEntries(response.headers.entries()));
      
      const responseData = await response.json();
      console.log('Coze上传响应数据:', responseData);
      
      if (!response.ok) {
        const errorInfo = {
          status: response.status,
          statusText: response.statusText,
          data: responseData,
          headers: Object.fromEntries(response.headers.entries())
        };
        console.error('Coze上传失败详情:', errorInfo);
        throw new Error(`HTTP ${response.status}: ${responseData.msg || responseData.message || response.statusText}`);
      }
      
      return responseData;
    } catch (error) {
      console.error('上传图片到coze失败:', error);
      
      // 检查是否是网络错误
      if (error.name === 'TypeError' && error.message.includes('fetch')) {
        throw new Error('网络连接失败，可能是CORS问题或网络不可达');
      }
      
      // 检查是否是CORS错误
      if (error.message.includes('CORS') || error.message.includes('cross-origin')) {
        throw new Error('跨域请求被阻止，请检查CORS配置');
      }
      
      throw error;
    }
  }

  // 通过file_id获取图片永久地址
  async get_image_url_by_file_id (fileId, accessToken) {
    const requestBody = {
      parameters: {
        input: JSON.stringify({ file_id: fileId })
      },
      workflow_id: "7527555709244801087"  // 使用接口文档中的正确workflow_id
    };

    const requestOptions = {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
        'accept': 'application/json'
      },
      body: JSON.stringify(requestBody)
    };

    console.log('准备获取图片永久地址:', {
      url: 'https://api.coze.cn/v1/workflow/run',
      fileId: fileId,
      workflowId: "7527555709244801087",
      tokenPrefix: accessToken.substring(0, 20) + '...',
      requestBody: requestBody
    });

    try {
      const response = await fetch('https://api.coze.cn/v1/workflow/run', requestOptions);
      
      console.log('Workflow响应状态:', response.status, response.statusText);
      console.log('Workflow响应头:', Object.fromEntries(response.headers.entries()));
      
      const responseData = await response.json();
      console.log('Workflow响应数据:', responseData);
      
      if (!response.ok) {
        const errorInfo = {
          status: response.status,
          statusText: response.statusText,
          data: responseData,
          headers: Object.fromEntries(response.headers.entries())
        };
        console.error('Workflow执行失败详情:', errorInfo);
        throw new Error(`HTTP ${response.status}: ${responseData.msg || responseData.message || response.statusText}`);
      }
      
      return responseData;
    } catch (error) {
      console.error('获取图片永久地址失败:', error);
      
      // 检查是否是网络错误
      if (error.name === 'TypeError' && error.message.includes('fetch')) {
        throw new Error('网络连接失败，无法访问Coze Workflow API');
      }
      
      // 检查是否是CORS错误
      if (error.message.includes('CORS') || error.message.includes('cross-origin')) {
        throw new Error('跨域请求被阻止，无法访问Coze Workflow API');
      }
      
      throw error;
    }
  }

  // 完整的图片上传流程（根据图片上传逻辑文档修复）
  async upload_image_complete (file) {
    try {
      console.log('开始图片上传流程，文件:', file.name);
      
      // 1. 获取coze token
      console.log('步骤1: 获取coze token');
      const tokenResponse = await this.get_coze_token();
      console.log('Token响应:', tokenResponse);
      
      if (!tokenResponse || !tokenResponse.upload_key || !tokenResponse.data) {
        throw new Error('获取coze token失败');
      }

      const uploadToken = tokenResponse.upload_key;  // 用于上传的token
      const accessToken = tokenResponse.data;        // 用于获取永久地址的token

      console.log('上传Token:', uploadToken);
      console.log('访问Token:', accessToken);

      // 2. 上传图片到coze
      console.log('步骤2: 上传图片到coze');
      const uploadResponse = await this.upload_image_to_coze(file, uploadToken);
      console.log('上传响应:', uploadResponse);
      
      if (!uploadResponse || !uploadResponse.data || !uploadResponse.data.id) {
        throw new Error('上传图片失败');
      }

      const fileId = uploadResponse.data.id;
      console.log('获得文件ID:', fileId);

      // 3. 获取图片永久地址
      console.log('步骤3: 获取图片永久地址');
      const urlResponse = await this.get_image_url_by_file_id(fileId, accessToken);
      console.log('永久地址响应:', urlResponse);
      
      // 解析永久地址
      let permanentUrl = '';
      if (urlResponse && urlResponse.data) {
        try {
          // 根据接口文档，data字段是JSON字符串，需要解析
          let parsedData;
          if (typeof urlResponse.data === 'string') {
            parsedData = JSON.parse(urlResponse.data);
          } else {
            parsedData = urlResponse.data;
          }
          
          // 从解析后的数据中获取output字段
          if (parsedData && parsedData.output) {
            permanentUrl = parsedData.output;
          }
          
          console.log('解析后的数据:', parsedData);
          console.log('提取的永久地址:', permanentUrl);
        } catch (parseError) {
          console.warn('解析data失败:', parseError);
          console.warn('原始data:', urlResponse.data);
          
          // 如果解析失败，尝试直接使用data字段
          if (typeof urlResponse.data === 'string' && urlResponse.data.startsWith('http')) {
            permanentUrl = urlResponse.data;
          }
        }
      }
      
      console.log('解析得到的永久地址:', permanentUrl);
      
      return {
        success: true,
        file_id: fileId,
        permanent_url: permanentUrl,
        url_response: urlResponse,
        upload_info: uploadResponse.data
      };
    } catch (error) {
      console.error('完整图片上传流程失败:', error);
      throw error;
    }
  }
