  // 创建即梦任务（支持图生视频和数字人）
  async create_jimeng_img2video_task (token, img_url, prompt, model, duration = 5, audio_url = '', task_type = 1) {
    try {
      const requestData = {
        task_type: task_type, // 1: 图生视频, 2: 数字人
        first_image: img_url
      };

      if (task_type === 1) {
        // 图生视频模式
        requestData.prompt = prompt;
        requestData.model = model;
        requestData.duration = duration;
        if (audio_url) {
          requestData.mp3_url = audio_url;
        }
      } else if (task_type === 2) {
        // 数字人模式
        requestData.mp3_url = audio_url;
        // 数字人模式需要计算费用
        if (audio_url) {
          // 这里需要根据音频时长计算费用，暂时使用默认值
          requestData.money = 40; // 将在调用处计算具体费用
        }
      }

      const response = await fetch(ENDPOINTS.JIMENG_TASK_CREATE, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(requestData)
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('创建即梦任务失败:', error);
      throw error;
    }
  }


