  // ======================== 工单系统相关接口 ========================
  
  // 工单系统专用请求方法
  async ticketRequest(url, method, data, token) {
    const requestOptions = {
      method: method,
      headers: {
        'Content-Type': 'application/json',
        'accept': 'application/json'
      }
    };

    // 工单系统的token通过参数传递，不是header
    const requestData = { ...data };
    if (token) {
      requestData.token = token;
    }

    // 添加请求数据到body
    if (requestData) {
      requestOptions.body = JSON.stringify(requestData);
    }

    try {
      const response = await fetch(url, requestOptions);
      const responseData = await response.json();
      
      if (!response.ok) {
        throw { 
          status: response.status, 
          data: responseData,
          msg: responseData.msg || `HTTP ${response.status} error`
        };
      }
      
      return responseData;
    } catch (error) {
      console.error(`工单API请求失败 ${url}:`, error.message || error);
      
      // 如果是网络错误或JSON解析错误
      if (!error.status) {
        throw {
          code: 500,
          msg: '网络连接失败或服务器错误',
          data: null
        };
      }
      
      if (this._isAuthError(error)) {
        this._handleAuthExpired();
        throw {
          code: error.status || 500,
          msg: '登录已过期',
          data: error.data || null
        };
      }
      
      // 抛出统一格式的错误
      throw {
        code: error.status || 500,
        msg: error.msg || error.message || '请求失败',
        data: error.data || null
      };
    }
  }
  
