  /**
   * 简化的图片上传方法 - 上传文件并获取永久地址
   */
  async upload_image_simple(file) {
    try {
      console.log('开始简化图片上传流程，文件:', file.name);
      
      // 1. 获取coze token
      console.log('步骤1: 获取coze token');
      const tokenResponse = await this.get_coze_token();
      console.log('Token响应:', tokenResponse);
      
      if (!tokenResponse || !tokenResponse.upload_key) {
        throw new Error('获取coze token失败');
      }

      const uploadToken = tokenResponse.upload_key;
      const accessToken = tokenResponse.data; // 用于获取永久地址的token
      console.log('上传Token:', uploadToken);

      // 2. 上传图片到coze
      console.log('步骤2: 上传图片到coze');
      const uploadResponse = await this.upload_image_to_coze(file, uploadToken);
      console.log('上传响应:', uploadResponse);
      
      if (!uploadResponse || !uploadResponse.data || !uploadResponse.data.id) {
        throw new Error('上传图片失败');
      }

      const fileId = uploadResponse.data.id;
      console.log('获得文件ID:', fileId);

      // 3. 获取永久访问地址（而不是临时API端点）
      let permanentUrl = '';
      if (accessToken) {
        console.log('步骤3: 获取图片永久地址');
        try {
          const urlResponse = await this.get_image_url_by_file_id(fileId, accessToken);
          console.log('永久地址响应:', urlResponse);
          
          if (urlResponse && urlResponse.data) {
            let parsedData;
            if (typeof urlResponse.data === 'string') {
              parsedData = JSON.parse(urlResponse.data);
            } else {
              parsedData = urlResponse.data;
            }
            
            if (parsedData && parsedData.output) {
              permanentUrl = parsedData.output;
              console.log('获得永久地址:', permanentUrl);
            }
          }
        } catch (urlError) {
          console.warn('获取永久地址失败，将使用文件ID:', urlError.message);
        }
      }
      
      // 如果获取永久地址失败，返回错误（因为临时API端点无法公开访问）
      if (!permanentUrl) {
        throw new Error('无法获取图片永久地址，请重试');
      }
      
      return {
        success: true,
        file_id: fileId,
        temp_url: permanentUrl, // 现在返回的是真正可访问的永久地址
        upload_info: uploadResponse.data
      };
    } catch (error) {
      console.error('简化图片上传流程失败:', error);
      throw error;
    }
  }
  
