  // ======================== Cloudflare R2 图片上传相关 API ========================

  /**
   * 获取 Cloudflare R2 上传凭证
   * @param {string} fileName - 文件名（必填）
   * @param {string} contentType - 文件MIME类型（必填，如 'image/jpeg'）
   * @param {number} expiresIn - 过期时间（秒，默认3600）
   */
  async getCfR2Token(fileName, contentType, expiresIn = 3600) {
    return this.request(`${this.apiBase}/get_cf_r2_token`, 'POST', {
      file_name: fileName,
      content_type: contentType,
      expires_in: expiresIn
    });
  }

  /**
   * 上传文件到 Cloudflare R2
   * @param {string} uploadUrl - 预签名上传URL
   * @param {File} file - 要上传的文件
   * @param {string} contentType - 文件MIME类型
   */
  async uploadToR2(uploadUrl, file, contentType) {
    try {
      console.log('开始上传文件到R2:', {
        url: uploadUrl,
        fileName: file.name,
        fileSize: file.size,
        contentType: contentType
      });

      const response = await fetch(uploadUrl, {
        method: 'PUT',
        headers: {
          'Content-Type': contentType
        },
        body: file
      });

      console.log('R2上传响应状态:', response.status, response.statusText);

      if (!response.ok) {
        const errorText = await response.text();
        console.error('R2上传失败详情:', {
          status: response.status,
          statusText: response.statusText,
          error: errorText
        });
        throw new Error(`R2上传失败: HTTP ${response.status} - ${errorText || response.statusText}`);
      }

      console.log('R2上传成功');
      return { success: true };
    } catch (error) {
      console.error('上传文件到R2失败:', error);
      throw error;
    }
  }

  /**
   * 完整的图片上传到R2流程
   * @param {File} file - 要上传的图片文件
   * @returns {Promise<{success: boolean, public_url: string, file_key: string}>}
   */
  async uploadImageToR2(file) {
    try {
      console.log('开始完整R2图片上传流程，文件:', file.name);

      // 1. 获取上传凭证
      console.log('步骤1: 获取R2上传凭证');
      const tokenResponse = await this.getCfR2Token(
        file.name,
        file.type,
        3600
      );

      console.log('Token响应:', tokenResponse);

      if (!tokenResponse || tokenResponse.code !== 200 || !tokenResponse.data) {
        throw new Error(tokenResponse?.msg || '获取上传凭证失败');
      }

      const { upload_url, public_url, file_key, content_type } = tokenResponse.data;

      if (!upload_url || !public_url) {
        throw new Error('上传凭证数据不完整');
      }

      // 2. 上传文件到R2
      console.log('步骤2: 上传文件到R2');
      await this.uploadToR2(upload_url, file, content_type || file.type);

      console.log('步骤3: 上传完成，返回公开URL:', public_url);

      return {
        success: true,
        public_url,
        file_key,
        content_type: content_type || file.type
      };
    } catch (error) {
      console.error('完整R2图片上传流程失败:', error);
      throw error;
    }
  }

  /**
   * 通用文件上传方法（支持图片和视频）
   * @param {FormData} formData - 包含文件和token的FormData对象
   * @returns {Promise<{code: number, data: {url: string}, msg?: string}>}
   */
  async upload_file(formData) {
    // 使用R2上传流程
    const file = formData.get('file');
    if (!file) {
      throw new Error('没有找到要上传的文件');
    }

    try {
      // 判断文件类型，使用对应的上传方法
      if (file.type.startsWith('image/')) {
        const result = await this.uploadImageToR2(file);
        return {
          code: 200,
          data: {
            url: result.public_url
          }
        };
      } else if (file.type.startsWith('video/')) {
        // 对于视频文件，也使用R2上传（假设支持）
        const tokenResponse = await this.getCfR2Token(
          file.name,
          file.type,
          3600
        );

        if (!tokenResponse || tokenResponse.code !== 200 || !tokenResponse.data) {
          throw new Error(tokenResponse?.msg || '获取上传凭证失败');
        }

        const { upload_url, public_url, file_key, content_type } = tokenResponse.data;

        if (!upload_url || !public_url) {
          throw new Error('上传凭证数据不完整');
        }

        await this.uploadToR2(upload_url, file, content_type || file.type);

        return {
          code: 200,
          data: {
            url: public_url
          }
        };
      } else {
        throw new Error('不支持的文件类型');
      }
    } catch (error) {
      console.error('文件上传失败:', error);
      throw error;
    }
  }

