  updateStoryScene(token, scene_id, updateData) {
    const requestData = { token, user_type: 1, scene_id };
    const allowedFields = [
      'scene_number', 'characters', 'time', 'location', 'visual_description',
      'dialogue', 'narration', 'art_prompt', 'current_image_id', 'current_image_url',
      'current_video_id', 'current_video_url', 'current_audio_id', 'current_audio_url',
      'shot_type', 'camera_angle', 'camera_movement', 'video_prompt', 'audio_prompt', 'atmosphere'
    ];
    allowedFields.forEach(field => {
      if (updateData[field] !== undefined) {
        requestData[field] = updateData[field];
      }
    });
    return this.request(`${this.apiBase}/story_scene/update`, 'POST', requestData);
  }

