  insertStoryScene(token, sceneData) {
    const requestData = { token, user_type: 1 };
    const requiredFields = ['story_id', 'insert_position'];
    requiredFields.forEach(field => {
      if (sceneData[field] !== undefined) {
        requestData[field] = sceneData[field];
      }
    });
    if (sceneData.insert_position !== 'end' && sceneData.reference_scene_number !== undefined) {
      requestData.reference_scene_number = sceneData.reference_scene_number;
    }
    const allowedOptionalFields = ['characters', 'time', 'location', 'visual_description', 'dialogue', 'narration'];
    allowedOptionalFields.forEach(field => {
      if (sceneData[field] !== undefined && sceneData[field] !== '') {
        requestData[field] = sceneData[field];
      }
    });
    return this.request(`${this.apiBase}/story_scene/insert`, 'POST', requestData);
  }

