// src/api/FFmpegService.js
//
// 2026-09-29：素材处理不再在浏览器里跑 FFmpeg.wasm，改打**本机后端**接口：
//   GET  /api/canvas-local/ffmpeg/status   检查本机 ffmpeg（客户端 deps/ffmpeg/ffmpeg.exe）
//   POST /api/canvas-local/ffmpeg          合并音视频 / 裁剪音频 / 拼接视频
//   GET  /api/canvas-local/media/<name>    取回本机产物（页面播放 / 下载）
// 好处：首屏不再下 ~25MB 的 wasm；大文件不受浏览器内存限制；产物留在本机。
// 画布页面由客户端本机后端托管，与本机接口同源，所以默认走相对路径；
// 独立起 dev server 时可以设 CANVAS_LOCAL_API_BASE 指到本机后端。

const LOCAL_API_ROOT = String(process.env.CANVAS_LOCAL_API_BASE || '').replace(/\/$/, '');

const STATUS_URL = `${LOCAL_API_ROOT}/api/canvas-local/ffmpeg/status`;
const FFMPEG_URL = `${LOCAL_API_ROOT}/api/canvas-local/ffmpeg`;
const MEDIA_URL = `${LOCAL_API_ROOT}/api/canvas-local/media`;

const MIME_BY_FORMAT = {
  mp4: 'video/mp4',
  webm: 'video/webm',
  mov: 'video/quicktime',
  mp3: 'audio/mpeg',
  wav: 'audio/wav',
  m4a: 'audio/mp4',
  ogg: 'audio/ogg',
  aac: 'audio/aac'
};

const formatOf = (url, fallback) => {
  const match = String(url || '').split('?')[0].match(/\.([a-z0-9]{2,5})$/i);
  return match ? match[1].toLowerCase() : fallback;
};

const mimeOf = (format, fallback = 'application/octet-stream') =>
  MIME_BY_FORMAT[String(format || '').toLowerCase()] || fallback;

const mediaUrl = (name) =>
  `${MEDIA_URL}/${String(name || '')
    .split('/')
    .filter((part) => part && part !== '.' && part !== '..')
    .map(encodeURIComponent)
    .join('/')}`;

const timestamp = () => Date.now();

const report = (onProgress, value) => {
  if (typeof onProgress === 'function') {
    onProgress(Math.max(0, Math.min(100, Math.round(value))));
  }
};

const describeError = async (resp) => {
  try {
    const data = await resp.json();
    const detail = data && (data.detail || data.message || data.error);
    if (typeof detail === 'string' && detail) return detail;
    if (detail) return JSON.stringify(detail);
  } catch (error) {
    // 上游不是 JSON 错误体（例如反代返回的 HTML），退回状态行
  }
  return `${resp.status} ${resp.statusText || ''}`.trim();
};

async function runLocalFfmpeg(payload) {
  let resp;
  try {
    resp = await fetch(FFMPEG_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
  } catch (error) {
    throw new Error(`连不上本机素材处理服务（客户端后端没起来？）：${error.message}`);
  }
  if (!resp.ok) {
    throw new Error(`本机素材处理失败：${await describeError(resp)}`);
  }
  const data = await resp.json().catch(() => null);
  if (!data || data.ok === false || !(data.name || data.output)) {
    throw new Error('本机素材处理没有返回产物');
  }
  return data;
}

async function fetchResultBlob(data, fallbackMime) {
  const url = data.url || mediaUrl(data.name);
  let resp;
  try {
    resp = await fetch(url);
  } catch (error) {
    throw new Error(`取回本机产物失败：${error.message}`);
  }
  if (!resp.ok) {
    throw new Error(`取回本机产物失败：${await describeError(resp)}`);
  }
  const raw = await resp.blob();
  if (!raw.size) {
    throw new Error('本机产物是空文件');
  }
  if (raw.type) return raw;
  const buffer = await raw.arrayBuffer();
  return new Blob([buffer], { type: fallbackMime });
}

class FFmpegService {
  constructor() {
    // 兼容旧字段：本机模式下没有 wasm 实例，ffmpeg 保持 null
    this.ffmpeg = null;
    this.loaded = false;
    this.loading = false;
    this.loadProgress = 0;
    this.loadCallbacks = [];
    this.engine = '';
  }

  /**
   * 检查本机素材处理服务（客户端 deps/ffmpeg/ffmpeg.exe）
   * @param {Function} onProgress - 进度回调（0-100）
   */
  async load(onProgress = null) {
    if (this.loaded) {
      report(onProgress, 100);
      return;
    }

    if (this.loading) {
      console.log('[FFmpeg] 正在检查本机 ffmpeg，等待完成...');
      return new Promise((resolve, reject) => {
        this.loadCallbacks.push({ resolve, reject });
      });
    }

    this.loading = true;
    try {
      report(onProgress, 10);
      let resp;
      try {
        resp = await fetch(STATUS_URL);
      } catch (error) {
        throw new Error(`连不上本机素材处理服务（客户端后端没起来？）：${error.message}`);
      }
      const status = resp.ok ? await resp.json().catch(() => null) : null;
      if (!status || status.ok === false) {
        const detail = (status && (status.detail || status.ffmpeg)) || (await describeError(resp));
        throw new Error(`本机 ffmpeg 未就绪：${detail || '未找到 deps/ffmpeg/ffmpeg.exe'}`);
      }

      this.engine = String(status.ffmpeg || '');
      report(onProgress, 100);
      this.loaded = true;
      this.loading = false;
      this.loadProgress = 100;
      console.log('[FFmpeg] 本机 ffmpeg 就绪:', this.engine);
      this.loadCallbacks.forEach(({ resolve }) => resolve());
      this.loadCallbacks = [];
    } catch (error) {
      this.loading = false;
      console.error('[FFmpeg] 本机 ffmpeg 不可用:', error.message);
      this.loadCallbacks.forEach(({ reject }) => reject(error));
      this.loadCallbacks = [];
      throw error;
    }
  }

  /**
   * 下载远程文件（兼容旧接口，返回 Uint8Array）
   */
  async downloadFile(url) {
    if (!url) {
      throw new Error('下载失败: URL 为空');
    }
    const target = url.startsWith('blob:') || url.startsWith('data:')
      ? url
      : `${url}${url.includes('?') ? '&' : '?'}_t=${timestamp()}`;
    const resp = await fetch(target, { cache: 'no-store' });
    if (!resp.ok) {
      throw new Error(`下载失败: ${await describeError(resp)}`);
    }
    return new Uint8Array(await resp.arrayBuffer());
  }

  /**
   * 合并视频 + 音频（在本机 ffmpeg 执行）
   * @returns {Promise<{blob: Blob, url: string, size: number, type: string, name: string}>}
   */
  async mergeVideoAudio(videoUrl, audioUrl, options = {}) {
    if (!videoUrl) throw new Error('缺少视频地址');
    if (!audioUrl) throw new Error('缺少音频地址');

    const {
      onProgress,
      outputFormat = 'mp4',
      mode = 'mix',
      durationMode = 'video',
      audioVolume = 1,
      audioOffset = 0,
      fadeIn = 0,
      fadeOut = 0
    } = options || {};

    const payload = {
      op: 'merge_video_audio',
      video_url: videoUrl,
      audio_url: audioUrl,
      output_format: outputFormat,
      audio_format: formatOf(audioUrl, 'mp3'),
      output_name: `merge_${timestamp()}.${outputFormat}`,
      mode,
      duration_mode: durationMode,
      audio_volume: audioVolume,
      audio_offset: audioOffset,
      fade_in: fadeIn,
      fade_out: fadeOut
    };

    console.log('[FFmpegService] 本机合并音视频:', payload);
    report(onProgress, 10);
    const data = await runLocalFfmpeg(payload);
    report(onProgress, 85);
    const blob = await fetchResultBlob(data, mimeOf(outputFormat, 'video/mp4'));
    report(onProgress, 100);
    console.log('[FFmpegService] ✓ 本机合并完成:', data.output, `${(blob.size / 1024 / 1024).toFixed(2)} MB`);
    return { blob, url: URL.createObjectURL(blob), size: blob.size, type: blob.type, name: data.name || '', output: data.output || '' };
  }

  /**
   * 裁剪音频（在本机 ffmpeg 执行）
   * @returns {Promise<{blob: Blob, url: string, size: number, type: string, outputFormat: string, name: string}>}
   */
  async trimAudio(audioUrl, options = {}) {
    if (!audioUrl) throw new Error('缺少音频地址');

    const { start = 0, end = null, outputFormat = 'mp3', onProgress } = options || {};
    const startSec = Number(start);
    if (Number.isNaN(startSec) || startSec < 0) throw new Error('开始时间不能小于 0');
    const endSec = end === null || end === undefined || end === '' ? null : Number(end);
    if (endSec !== null && (Number.isNaN(endSec) || endSec <= startSec)) {
      throw new Error('结束时间必须大于开始时间');
    }

    const payload = {
      op: 'trim_audio',
      audio_url: audioUrl,
      audio_format: formatOf(audioUrl, outputFormat),
      output_format: outputFormat,
      output_name: `trim_${timestamp()}.${outputFormat}`,
      start: startSec,
      end: endSec
    };

    console.log('[FFmpegService] 本机裁剪音频:', payload);
    report(onProgress, 10);
    const data = await runLocalFfmpeg(payload);
    report(onProgress, 85);
    const blob = await fetchResultBlob(data, mimeOf(outputFormat, 'audio/mpeg'));
    report(onProgress, 100);
    console.log('[FFmpegService] ✓ 本机裁剪完成:', data.output, `${(blob.size / 1024 / 1024).toFixed(2)} MB`);
    return {
      blob,
      url: URL.createObjectURL(blob),
      size: blob.size,
      type: blob.type,
      outputFormat,
      name: data.name || '',
      output: data.output || ''
    };
  }

  /**
   * 拼接视频（在本机 ffmpeg 执行）
   * @returns {Promise<{blob: Blob, url: string, size: number, type: string, name: string}>}
   */
  async concatVideos(videoUrls, options = {}) {
    const urls = Array.isArray(videoUrls) ? videoUrls.filter(Boolean) : [];
    if (urls.length < 2) {
      throw new Error('视频拼接需要至少连接2个视频');
    }

    const { outputFormat = 'mp4', onProgress } = options || {};
    const payload = {
      op: 'concat_videos',
      urls,
      output_format: outputFormat,
      output_name: `concat_${timestamp()}.${outputFormat}`
    };

    console.log('[FFmpegService] 本机拼接视频:', payload);
    report(onProgress, 10);
    const data = await runLocalFfmpeg(payload);
    report(onProgress, 85);
    const blob = await fetchResultBlob(data, mimeOf(outputFormat, 'video/mp4'));
    report(onProgress, 100);
    console.log('[FFmpegService] ✓ 本机拼接完成:', data.output, `${(blob.size / 1024 / 1024).toFixed(2)} MB`);
    return { blob, url: URL.createObjectURL(blob), size: blob.size, type: blob.type, name: data.name || '', output: data.output || '' };
  }

  /**
   * 兼容旧接口：按地址猜扩展名
   */
  getFileExtension(url) {
    return formatOf(url, 'mp3');
  }

  /**
   * 获取加载状态
   */
  getLoadStatus() {
    return {
      loaded: this.loaded,
      loading: this.loading,
      progress: this.loadProgress,
      engine: this.engine
    };
  }

  /**
   * 释放（本机模式无需 terminate，只重置状态）
   */
  async unload() {
    this.ffmpeg = null;
    this.loaded = false;
    this.loading = false;
    this.loadProgress = 0;
  }
}

export default new FFmpegService();