.InspirationCanvas-loading,
.InspirationCanvas-no-more,
.InspirationCanvas-empty-message {
  text-align: center;
  padding: 3rem;
  color: #94a3b8;
  font-size: 0.95rem;
  font-weight: 500;
  width: 100%;
}

.InspirationCanvas-error {
  text-align: center;
  padding: 2rem;
  background: #fef2f2;
  border-radius: 12px;
  border: 1px solid #fecaca;
  margin-bottom: 2rem;
  color: #b91c1c;
}

/* 对话框样式 */
.InspirationCanvas-dialog-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.6); /* 加深背景 */
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 1rem;
}

.InspirationCanvas-dialog {
  background: white;
  border-radius: 24px;
  padding: 2.5rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
  animation: dialogPop 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes dialogPop {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.InspirationCanvas-dialog-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: #0f172a;
  margin: 0 0 1.5rem 0;
  text-align: center;
}

.InspirationCanvas-form-input,
.InspirationCanvas-form-textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  font-size: 1rem;
  transition: all 0.2s;
  background: #f8fafc;
  color: #1e293b;
}

.InspirationCanvas-form-input:focus,
.InspirationCanvas-form-textarea:focus {
  background: white;
  border-color: #0f172a;
  box-shadow: 0 0 0 4px rgba(15, 23, 42, 0.05);
  outline: none;
}

.InspirationCanvas-dialog-actions {
  display: flex;
  gap: 12px;
  margin-top: 2rem;
}

.InspirationCanvas-dialog-button {
  flex: 1;
  padding: 12px;
  border-radius: 12px;
  font-weight: 600;
  font-size: 1rem;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.InspirationCanvas-dialog-button-cancel {
  background: #f1f5f9;
  color: #64748b;
}

.InspirationCanvas-dialog-button-cancel:hover {
  background: #e2e8f0;
  color: #334155;
}

.InspirationCanvas-dialog-button-save {
  background: #0f172a;
  color: white;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.2);
}

.InspirationCanvas-dialog-button-save:hover {
  background: #1e293b;
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(15, 23, 42, 0.25);
}

.InspirationCanvas-dialog-button-delete {
  background: #ef4444;
  color: white;
  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.2);
}

.InspirationCanvas-dialog-button-delete:hover {
  background: #dc2626;
  transform: translateY(-1px);
}

.InspirationCanvas-cover-dialog {
  max-width: 760px;
  padding: 24px;
}

.InspirationCanvas-cover-dialog-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.InspirationCanvas-cover-dialog-header .InspirationCanvas-dialog-title {
  margin-bottom: 6px;
  text-align: left;
}

.InspirationCanvas-cover-dialog-subtitle {
  margin: 0;
  color: #737b75;
  font-size: 12px;
  line-height: 1.5;
}

.InspirationCanvas-cover-dialog-close {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  place-items: center;
  padding: 0;
  color: #737b75;
  background: #f1f3f2;
  border: 1px solid #e1e7e3;
  border-radius: 8px;
  cursor: pointer;
  transition: color 160ms ease, background 160ms ease, border-color 160ms ease;
}

.InspirationCanvas-cover-dialog-close:hover {
  color: #171a17;
  background: #e7ebe8;
  border-color: #d3dbd5;
}

.InspirationCanvas-cover-dialog-close:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.InspirationCanvas-cover-picker {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  max-height: min(55vh, 460px);
  overflow-y: auto;
  padding: 2px;
}

.InspirationCanvas-cover-option {
  min-width: 0;
  padding: 0;
  color: #4f5b52;
  text-align: left;
  background: #fff;
  border: 1px solid #dfe5e1;
  border-radius: 9px;
  cursor: pointer;
  overflow: hidden;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.InspirationCanvas-cover-option:hover {
  border-color: #a9c880;
  box-shadow: 0 6px 16px rgba(54, 73, 57, 0.11);
  transform: translateY(-1px);
}

.InspirationCanvas-cover-option:focus-visible,
.InspirationCanvas-cover-dialog-close:focus-visible,
.InspirationCanvas-cover-upload-button:focus-visible,
.InspirationCanvas-cover-retry:focus-visible {
  outline: 3px solid rgba(126, 174, 71, 0.3);
  outline-offset: 2px;
}

.InspirationCanvas-cover-option.is-selected {
  border-color: #7eae47;
  box-shadow: 0 0 0 2px rgba(126, 174, 71, 0.2);
}

.InspirationCanvas-cover-option-image {
  position: relative;
  display: block;
  aspect-ratio: 4 / 3;
  background: #e8eeea;
}

.InspirationCanvas-cover-option-image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.InspirationCanvas-cover-option-check {
  position: absolute;
  top: 8px;
  right: 8px;
  display: grid;
  width: 26px;
  height: 26px;
  place-items: center;
  color: #fff;
  background: #7eae47;
  border-radius: 50%;
  box-shadow: 0 2px 8px rgba(40, 62, 34, 0.24);
}

.InspirationCanvas-cover-option-label {
  display: block;
  overflow: hidden;
  padding: 9px 10px 10px;
  color: #4f5b52;
  font-size: 11px;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.InspirationCanvas-cover-state {
  display: flex;
  min-height: 180px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 24px;
  color: #5e6a61;
  background: #f5f7f5;
  border: 1px dashed #d3ddd5;
  border-radius: 9px;
  font-size: 13px;
}

.InspirationCanvas-cover-state.is-error,
.InspirationCanvas-cover-state.is-empty {
  flex-direction: column;
  text-align: center;
}

.InspirationCanvas-cover-state.is-error {
  color: #a33c37;
  background: #fff5f3;
  border-color: #efc1bc;
}

.InspirationCanvas-cover-state.is-error span,
.InspirationCanvas-cover-state.is-empty span {
  color: #737b75;
  font-size: 12px;
}

.InspirationCanvas-cover-retry {
  padding: 7px 12px;
  color: #4f7e2e;
  background: #e3f3cb;
  border: 1px solid #b9df8a;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.InspirationCanvas-cover-retry:hover {
  background: #d8efb9;
  border-color: #8fbd5c;
}

.InspirationCanvas-cover-retry:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.InspirationCanvas-cover-state.is-empty svg {
  color: #9aaa9d;
  margin-bottom: 2px;
}

.InspirationCanvas-cover-spinner {
  width: 16px;
  height: 16px;
  border: 2px solid #d7e2ce;
  border-top-color: #7eae47;
  border-radius: 50%;
  animation: InspirationCanvas-cover-spin 700ms linear infinite;
}

@keyframes InspirationCanvas-cover-spin {
  to { transform: rotate(360deg); }
}

.InspirationCanvas-cover-dialog-footer {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-top: 20px;
}

.InspirationCanvas-cover-dialog-footer .InspirationCanvas-dialog-actions {
  min-width: 260px;
  margin-top: 0;
}

.InspirationCanvas-cover-upload-button {
  padding: 10px 2px;
  color: #657461;
  background: transparent;
  border: 0;
  font-size: 12px;
  cursor: pointer;
}

.InspirationCanvas-cover-upload-button:hover {
  color: #4f7e2e;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.InspirationCanvas-cover-upload-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

/* 升级弹窗相关复用 */
.InspirationCanvas-upgrade-dialog {
  text-align: center;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
}

.InspirationCanvas-upgrade-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  margin: 0 auto 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fef3c7;
  color: #d97706;
}

.InspirationCanvas-upgrade-message {
  background: #f0f9ff;
  border: 1px solid #bae6fd;
  color: #0369a1;
  padding: 1rem;
  border-radius: 12px;
  margin-bottom: 1.5rem;
  font-size: 0.95rem;
}

.InspirationCanvas-upgrade-benefits {
  list-style: none;
  padding: 0;
  margin: 0 0 2rem 0;
  text-align: left;
}

.InspirationCanvas-upgrade-benefits li {
  padding: 0.5rem 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: #475569;
}

.InspirationCanvas-upgrade-benefits li::before {
  content: '✓';
  color: #10b981;
  font-weight: 800;
}

.InspirationCanvas-upgrade-button {
  background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%);
  color: white;
}

/* 移动端适配 */
@media (max-width: 768px) {
  .InspirationCanvas-body {
    width: calc(100% - 76px);
    margin-left: 76px;
  }

  .InspirationCanvas-header-inner {
    min-height: 150px;
    padding: 24px 12px 20px;
  }

  .InspirationCanvas-main {
    padding: 1rem 1rem 3rem;
  }

  .InspirationCanvas-campaign {
    grid-template-columns: 1fr;
    gap: 22px;
    padding: 24px;
  }

  .InspirationCanvas-campaign-reward {
    grid-template-columns: auto auto 1fr;
    min-width: 0;
    justify-items: start;
    align-items: baseline;
    gap: 6px;
    padding: 20px 0 0;
    border-top: 1px solid #d7e2ce;
    border-left: 0;
  }

  .InspirationCanvas-campaign-reward > strong { font-size: 38px; }
  .InspirationCanvas-campaign-reward button { grid-column: 1 / -1; }
  
  .InspirationCanvas-masonry-container {
    gap: 2px;
  }
  
  .InspirationCanvas-masonry-column {
    gap: 2px;
  }

  .InspirationCanvas-skeleton-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  
  .InspirationCanvas-create-card {
    min-height: 160px;
  }

  .InspirationCanvas-login-prompt {
    grid-template-columns: auto 1fr;
    gap: 14px;
    padding: 22px;
  }

  .InspirationCanvas-login-prompt button { grid-column: 1 / -1; }
}

@media (max-width: 720px) {
  .InspirationCanvas-header .InspirationCanvas-header-inner {
    min-height: 140px;
    padding: 20px 10px;
  }

  .InspirationCanvas-heading h1 {
    gap: 8px;
    font-size: 24px;
  }

  .InspirationCanvas-heading h1 .InspirationCanvas-brand-logo {
    width: calc(100% - 108px);
    max-width: 100%;
  }

  .InspirationCanvas-body {
    width: calc(100% - 68px);
    margin-left: 68px;
  }
}

@media (max-width: 620px) {
  .InspirationCanvas-skeleton-grid {
    grid-template-columns: 1fr;
  }

  .InspirationCanvas-cover-dialog {
    padding: 18px;
  }

  .InspirationCanvas-cover-picker {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 9px;
    max-height: 52vh;
  }

  .InspirationCanvas-cover-dialog-footer {
    align-items: stretch;
    flex-direction: column-reverse;
    gap: 8px;
  }

  .InspirationCanvas-cover-dialog-footer .InspirationCanvas-dialog-actions {
    width: 100%;
    min-width: 0;
  }

  .InspirationCanvas-cover-upload-button {
    align-self: flex-start;
  }

  .InspirationCanvas-body.is-mine .InspirationCanvas-main {
    padding: 28px 14px 56px;
  }

  .InspirationCanvas-section-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 14px;
    margin-bottom: 22px;
  }

  .InspirationCanvas-create-project-button {
    width: 100%;
    justify-content: center;
  }

  .InspirationCanvas-masonry-container.is-mine-projects {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}
