t-size: clamp(30px, 3.2vw, 52px);\n  font-weight: 400;\n  letter-spacing: 0;\n  line-height: 1.03;\n  white-space: nowrap;\n}\n\n.InspirationCanvas-brand-logo {\n  display: block;\n  width: min(360px, 76vw);\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n}\n\n.InspirationCanvas-heading .InspirationCanvas-brand-logo {\n  max-width: 100%;\n}\n\n.InspirationCanvas-heading h1 .InspirationCanvas-brand-logo {\n  width: min(360px, calc(100% - 120px));\n  max-width: 100%;\n  margin: 0;\n  flex: 0 1 auto;\n}\n\n/* Tab 切换样式 - 左侧对齐 */\n.InspirationCanvas-tabs {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n}\n\n.InspirationCanvas-tab {\n  min-width: 92px;\n  padding: 10px 15px;\n  color: #74796f;\n  border: 1px solid #bdbbb1;\n  border-radius: 999px;\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: #94a3b8;\n  cursor: pointer;\n  transition: all 0.3s ease;\n  position: relative;\n  user-select: none;\n}\n\n.InspirationCanvas-tab span {\n  margin-left: 5px;\n  font-family: Georgia, serif;\n}\n\n.InspirationCanvas-tab:hover {\n  color: #1e293b;\n}\n\n.InspirationCanvas-tab.active {\n  color: #11120f;\n  background: #d8ff45;\n  border-color: #11120f;\n  font-size: 0.82rem;\n}\n\n.InspirationCanvas-tab.active::after {\n  display: none;\n}\n\n/* 主内容区 */\n.InspirationCanvas-main {\n  padding: 2rem 2rem 4rem;\n  max-width: 1800px;\n  width: 100%;\n  margin: 0 auto;\n  flex: 1;\n}\n\n.InspirationCanvas-body.is-mine .InspirationCanvas-header {\n  display: none;\n}\n\n.InspirationCanvas-body.is-mine .InspirationCanvas-main {\n  padding-top: 30px;\n}\n\n.InspirationCanvas-section-header {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 24px;\n  margin-bottom: 18px;\n}\n\n.InspirationCanvas-section-header h2 {\n  margin: 0;\n  color: #171a17;\n  font-size: 21px;\n  font-weight: 720;\n  letter-spacing: 0;\n  line-height: 1.2;\n}\n\n.InspirationCanvas-section-header p {\n  margin: 0 0 2px;\n  color: #737b75;\n  font-size: 12px;