const formatCampaignTime = (value) => {
  if (!value) return '—';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toLocaleString('zh-CN', {
    timeZone: 'Asia/Shanghai',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });
};

const getProjectDateValue = (project) => (
  project?.updated_at
  || project?.created_at
  || project?.last_accessed_at
  || project?.modified_at
  || ''
);

const getProjectTimestamp = (project) => {
  const value = getProjectDateValue(project);
  const timestamp = value ? new Date(value).getTime() : Number.NaN;
  return Number.isFinite(timestamp) ? timestamp : 0;
};

const sortProjectsNewestFirst = (projects) => [...projects].sort((left, right) => {
  const timeDifference = getProjectTimestamp(right) - getProjectTimestamp(left);
  if (timeDifference !== 0) return timeDifference;
  return String(right?.uuid || right?.id || '').localeCompare(
    String(left?.uuid || left?.id || ''),
    undefined,
    { numeric: true }
  );
});

const formatProjectDate = (value) => {
  if (!value) return '时间未知';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '时间未知';
  return date.toLocaleDateString('zh-CN', {
    timeZone: 'Asia/Shanghai',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
};

const getProjectStableKey = (project) => String(
  project?.uuid || project?.id || project?.name || ''
);

export const getProjectCoverUrl = (project) => {
  const coverUrl = [
    project?.thumbnail_url,
    project?.thumbnailUrl,
    project?.cover_url,
    project?.coverUrl
  ].find((value) => typeof value === 'string' && value.trim());
  return coverUrl ? coverUrl.trim() : '';
};

export const hasProjectCover = (project) => Boolean(getProjectCoverUrl(project));

const parseImageRatio = (value) => {
  if (typeof value === 'number' && Number.isFinite(value) && value > 0) {
    return value;
  }

  if (typeof value !== 'string') return null;
  const normalized = value.trim();
  if (!normalized) return null;

  const ratioParts = normalized.split(/[:/x]/i).map(Number);
  if (ratioParts.length === 2 && ratioParts.every((part) => Number.isFinite(part) && part > 0)) {
    return ratioParts[0] / ratioParts[1];
  }

  const numericRatio = Number(normalized);
  return Number.isFinite(numericRatio) && numericRatio > 0 ? numericRatio : null;
};

const getProjectImageRatio = (project, knownRatios = {}) => {
  const knownRatio = parseImageRatio(knownRatios[getProjectStableKey(project)]);
  if (knownRatio) return knownRatio;

  const dimensions = project?.thumbnail || project?.cover || project?.dimensions || {};
  const width = Number(
    project?.thumbnail_width
    || project?.cover_width
    || project?.width
    || dimensions.width
  );
  const height = Number(
    project?.thumbnail_height
    || project?.cover_height
    || project?.height
    || dimensions.height
  );
  if (width > 0 && height > 0) return width / height;

  return parseImageRatio(
    project?.thumbnail_aspect_ratio
    || project?.cover_aspect_ratio
    || project?.aspect_ratio
  ) || 4 / 3;
};

export const distributeProjectsIntoMasonryColumns = (projects, columnCount, knownRatios = {}) => {
  const safeColumnCount = Math.max(1, Math.floor(Number(columnCount) || 1));
  const columns = Array.from({ length: safeColumnCount }, () => []);
  const estimatedHeights = Array(safeColumnCount).fill(0);

  (Array.isArray(projects) ? projects : []).forEach((project) => {
    let shortestColumnIndex = 0;
    for (let index = 1; index < estimatedHeights.length; index += 1) {
      if (estimatedHeights[index] < estimatedHeights[shortestColumnIndex]) {
        shortestColumnIndex = index;
      }
    }

    columns[shortestColumnIndex].push(project);
    const imageRatio = getProjectImageRatio(project, knownRatios);
    estimatedHeights[shortestColumnIndex] += (1 / imageRatio) + 0.16;
  });

  return columns;
};

const MASONRY_SKELETON_RATIOS = [
  0.82, 1.14, 0.72, 1.28, 0.96, 0.78, 1.2, 0.9
];

const MasonrySkeletonGrid = ({ columns, compact = false }) => {
  const skeletonCount = Math.max(columns * 2, 6);
  const skeletons = Array.from({ length: skeletonCount }, (_, index) => ({
    id: `skeleton-${index}`,
    ratio: compact ? 16 / 9 : MASONRY_SKELETON_RATIOS[index % MASONRY_SKELETON_RATIOS.length]
  }));

  return (
    <div
      className="InspirationCanvas-skeleton-grid"
      style={{ '--InspirationCanvas-skeleton-columns': columns }}
      role="status"
      aria-label="正在加载作品"
    >
      {skeletons.map((skeleton) => (
        <div className="InspirationCanvas-skeleton-item" key={skeleton.id}>
          <div
            className="InspirationCanvas-skeleton-card"
            style={{ aspectRatio: skeleton.ratio }}
            aria-hidden="true"
          >
            <span className="InspirationCanvas-skeleton-shimmer" />
          </div>
        </div>
      ))}
    </div>
  );
};

const getGeneratedImageUrl = (image) => {
  if (typeof image === 'string') return image;
  return image?.url || image?.image_url || image?.imageUrl || null;
};

export const extractProjectGeneratedImages = (snapshot) => {
  const nodes = Array.isArray(snapshot?.nodes) ? snapshot.nodes : [];
  const seenUrls = new Set();

  return nodes.flatMap((node) => {
    const generatedImages = Array.isArray(node?.data?.generatedImages)
      ? node.data.generatedImages
      : [];
    const nodeLabel = node?.data?.modelId || node?.data?.taskType || '生成结果';

    return generatedImages.reduce((images, image, index) => {
      const url = getGeneratedImageUrl(image);
      if (
        typeof url !== 'string'
        || !url
        || url.startsWith('data:')
        || url.startsWith('blob:')
        || seenUrls.has(url)
      ) {
        return images;
      }

      seenUrls.add(url);
      images.push({
        id: `${node?.id || 'node'}-${index}-${url}`,
        url,
        label: nodeLabel,
        index: index + 1
      });
      return images;
    }, []);
  });
};

