  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      if (width >= 1920) setNumColumns(6);
      else if (width >= 1440) setNumColumns(5);
      else if (width >= 1024) setNumColumns(4);
      else if (width >= 640) setNumColumns(3);
      else setNumColumns(2);
    };
    
    handleResize(); // Initial check
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const extractErrorMessage = (err, defaultMsg = '操作失败') => {
    if (!err) return defaultMsg;
    if (typeof err === 'string') return err;

    if (err.data) {
      if (typeof err.data === 'string') {
        try {
          const parsed = JSON.parse(err.data);
          if (parsed) {
            if (Array.isArray(parsed.detail)) {
              return parsed.detail.join('; ');
            }
            if (parsed.detail) {
              return parsed.detail;
            }
            if (parsed.message) {
              return parsed.message;
            }
            if (parsed.msg) {
              return parsed.msg;
            }
          }
        } catch (parseError) {
          if (err.data.trim()) {
            return err.data;
          }
        }
      } else if (typeof err.data === 'object' && err.data !== null) {
        if (Array.isArray(err.data.detail)) {
          return err.data.detail.join('; ');
        }
        if (err.data.detail && typeof err.data.detail === 'object') {
          return err.data.detail.message || err.data.detail.reason || defaultMsg;
        }
        return err.data.detail || err.data.message || err.data.msg || defaultMsg;
      }
    }

    if (err.message && typeof err.message === 'string') {
      return err.message;
    }

    return defaultMsg;
  };

