/* 字段容器 */
.KlingLipSyncNode-field {
  margin-bottom: 16px;
}

/* 标签 */
.KlingLipSyncNode-label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: #374151;
  margin-bottom: 8px;
}

.KlingLipSyncNode-optional {
  font-weight: 400;
  color: #9ca3af;
  font-size: 11px;
}

/* 按钮组 */
.KlingLipSyncNode-button-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.KlingLipSyncNode-button {
  padding: 10px 16px;
  border: 2px solid #e5e7eb;
  border-radius: 8px;
  background: white;
  color: #6b7280;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.KlingLipSyncNode-button:hover:not(:disabled) {
  border-color: #ec4899;
  color: #ec4899;
  background: #fdf2f8;
}

.KlingLipSyncNode-button-active {
  border-color: #ec4899;
  background: linear-gradient(135deg, #ec4899 0%, #db2777 100%);
  color: white;
}

.KlingLipSyncNode-button-active:hover:not(:disabled) {
  background: linear-gradient(135deg, #db2777 0%, #be185d 100%);
}

.KlingLipSyncNode-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

