  padding: 10px 12px;
  border: 2px solid #e5e7eb;
  border-radius: 8px;
  font-size: 13px;
  background: white;
  cursor: pointer;
  transition: all 0.2s ease;
}

.KlingLipSyncNode-select:focus {
  outline: none;
  border-color: #ec4899;
  background: #fdf2f8;
}

.KlingLipSyncNode-select:disabled {
  background: #f9fafb;
  color: #9ca3af;
  cursor: not-allowed;
}

