/**
 * 获取指定类型的模型配置
 * @param {string} mode - 模型类型: 'image' | 'video' | 'audio'
 * @returns {Array} 模型配置数组
 */
export const getModelsByMode = (mode) => {
  return MODEL_CONFIGS[mode] || [];
};

/**
 * 获取模型的默认数据
 * @param {string} modelType - 模型节点类型
 * @returns {Object} 默认数据对象
 */
export const getDefaultModelData = (modelType) => {
  const defaultDataMap = {
    // 图像模型
    gptImage2: { aspectRatio: '4:3', resolution: '1K', quality: 'low', outputFormat: 'png' },
    nanoBanana2: { aspectRatio: 'auto', resolution: '1K', numImages: 1, outputFormat: 'png' },
    imengImageGen: { prompt: '', mode: 'text2image' },
    minimaxImage: { prompt: '' },
    googleBanana: { prompt: '' },
    textToImage: { prompt: '' },
    referenceToImage: { prompt: '' },

    // 视频模型
    minimaxH3Video: { duration: 5, aspectRatio: '16:9', resolution: '768P' },
    klingO3ReferenceVideo: { duration: 5, aspectRatio: '16:9', resolution: 'Standard', generateAudio: true },
    geminiOmniFlashVideo: { duration: 5, aspectRatio: '16:9', resolution: '720P' },
    superSeed2LiteVideo: { duration: 6, aspectRatio: '16:9', resolution: '480p' },
    sora2Video: { prompt: '' },
    veo3Video: { prompt: '' },
    klingVideo: { prompt: '' },
    hailuo23Video: { prompt: '' },
    doubaoVideo: { prompt: '' },

    // 音频模型
    textToAudio: { text: '' },
    hailuoMusic: { prompt: '' },
  };

  return defaultDataMap[modelType] || {};
};

