const QUALITY_OPTIONS = [
  { value: 'low', label: '快速', detail: '响应更快' },
  { value: 'medium', label: '标准', detail: '平衡质量与速度' },
  { value: 'high', label: '精细', detail: '细节优先' },
];

const TERMINAL_STATUSES = new Set(['completed', 'failed']);
const HISTORY_PAGE_SIZE = 12;
const REFERENCE_TYPE_ORDER = ['image', 'video', 'audio'];
const REFERENCE_TYPE_OPTIONS = {
  image: {
    label: '参考图',
    icon: 'bi-image',
    accept: 'image/png,image/jpeg,image/webp,image/gif',
    extensions: 'PNG、JPG、WEBP',
  },
  video: {
    label: '参考视频',
    icon: 'bi-camera-reels',
    accept: 'video/mp4,video/quicktime,video/webm,video/x-matroska',
    extensions: 'MP4、MOV、WEBM',
  },
  audio: {
    label: '参考音频',
    icon: 'bi-music-note-beamed',
    accept: 'audio/mpeg,audio/wav,audio/ogg,audio/mp4,audio/aac,audio/flac',
    extensions: 'MP3、WAV、M4A',
  },
};

const REFERENCE_FILE_EXTENSIONS = {
  image: /\.(png|jpe?g|webp|gif)$/i,
  video: /\.(mp4|mov|webm|mkv)$/i,
  audio: /\.(mp3|wav|ogg|m4a|aac|flac)$/i,
};

const getStatusMeta = status => ({
  pending: { label: '排队中', className: 'is-pending' },
  processing: { label: '生成中', className: 'is-processing' },
  completed: { label: '已完成', className: 'is-completed' },
  failed: { label: '失败', className: 'is-failed' },
}[status] || { label: '等待提交', className: 'is-idle' });

const toMenuOptions = values => (values || []).map(option => (
  typeof option === 'string' ? { value: option, label: option } : option
));

const getMenuOptionLabel = (options, value) => (
  options.find(option => String(option.value) === String(value))?.label || String(value)
);

const isReferenceFile = (file, type) => (
  Boolean(file)
  && (file.type?.startsWith(`${type}/`) || REFERENCE_FILE_EXTENSIONS[type].test(file.name || ''))
);

const createReferencePreviewUrl = file => (
  typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function'
    ? URL.createObjectURL(file)
    : ''
);

const revokeReferencePreviewUrl = url => {
  if (url?.startsWith('blob:') && typeof URL !== 'undefined' && typeof URL.revokeObjectURL === 'function') {
    URL.revokeObjectURL(url);
  }
};

const parseMaybeJson = value => {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch (_) {
    return value;
  }
};

const collectMediaResults = value => {
  const results = [];
  const visited = new WeakSet();

  const addUrl = (url, metadata = {}, hint = '') => {
    if (typeof url !== 'string' || !/^https?:\/\//i.test(url)) return;
    if (/\.(mp3|wav|ogg|aac|m4a)(\?|$)/i.test(url)) return;
    if (results.some(result => result.url === url)) return;
    const type = /video|movie|clip/i.test(hint) || /\.(mp4|webm|mov|m4v)(\?|$)/i.test(url)
      ? 'video'
      : 'image';
    results.push({
      url,
      type,
      width: metadata.width,
      height: metadata.height,
      duration: metadata.duration,
    });
  };

  const visit = (current, hint = '') => {
    const parsed = parseMaybeJson(current);
    if (!parsed) return;
    if (typeof parsed === 'string') {
      addUrl(parsed, {}, hint);
      return;
    }
    if (typeof parsed !== 'object' || visited.has(parsed)) return;
    visited.add(parsed);

    if (Array.isArray(parsed)) {
      parsed.forEach(item => visit(item, hint));
    } else {
      addUrl(parsed.url || parsed.image_url || parsed.imageUrl || parsed.video_url || parsed.videoUrl, parsed, hint);
      Object.entries(parsed).forEach(([key, child]) => visit(child, key));
    }
  };

  visit(value);
  return results;
};

function GeneratePageOptionMenu({
  id,
  label,
  value,
  options,
  disabled,
  isOpen,
  onToggle,
  onSelect,
}) {
  const selectedOption = options.find(option => String(option.value) === String(value)) || options[0];
  const menuId = `${id}-options`;

  return (
    <div className="GeneratePage-option-field">
      <span>{label}</span>
      <div className={`GeneratePage-option-menu${isOpen ? ' is-open' : ''}`}>
        <button
          type="button"
          id={`${id}-trigger`}
          className="GeneratePage-option-trigger"
          aria-label={`${label}：${selectedOption?.label || value}`}
          aria-haspopup="listbox"
          aria-expanded={isOpen}
          aria-controls={menuId}
          disabled={disabled}
          onClick={() => onToggle(id)}
          onKeyDown={event => {
            if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
              event.preventDefault();
              onToggle(id);
            }
          }}
        >
          <span>{selectedOption?.label || value}</span>
          <i className="bi bi-chevron-down" aria-hidden="true" />
        </button>
        {isOpen && (
          <div id={menuId} className="GeneratePage-option-list" role="listbox" aria-label={`${label}选项`}>
            {options.map(option => {
              const isSelected = String(option.value) === String(value);
              return (
                <button
                  type="button"
                  role="option"
                  key={option.value}
                  aria-selected={isSelected}
                  className={isSelected ? 'is-selected' : ''}
                  onClick={() => onSelect(option.value)}
                  onKeyDown={event => {
                    if (event.key === 'Escape') {
                      event.preventDefault();
                      onToggle(null);
                    }
                  }}
                >
                  <span>{option.label}</span>
                  {option.detail && <small>{option.detail}</small>}
                  {isSelected && <i className="bi bi-check2" aria-hidden="true" />}
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

