.GeneratePage-params-toggle {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 38px;
  padding: 0;
  color: var(--canvas-ink, #171a17);
  background: transparent;
  border: 0;
  text-align: left;
}

.GeneratePage-params-toggle:hover:not(:disabled) .GeneratePage-params-toggle-copy strong {
  color: #36512d;
}

.GeneratePage-params-toggle:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.GeneratePage-params-toggle-mark {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  color: #668d4f;
  background: #edf5e8;
  border-radius: 7px;
  font-size: 12px;
