}

.GeneratePage-parameter-note {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 9px;
  color: #717d74;
  font-size: 9px;
  line-height: 1.45;
}

.GeneratePage-parameter-note i {
  padding-top: 1px;
  color: var(--canvas-green-strong, #70a33d);
}

.GeneratePage-submit-area {
  display: grid;
  gap: 8px;
}

.GeneratePage-quote {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 39px;
  padding: 6px 8px;
  color: #68736b;
  background: #f7f9f7;
  border: 1px solid #e7ece8;
  border-radius: 8px;
}

.GeneratePage-quote-icon {
  display: grid;
  width: 23px;
  height: 23px;
  flex: 0 0 23px;
  place-items: center;
  color: #6a9e39;
  background: #e6f2d8;
  border-radius: 6px;
  font-size: 11px;
}

.GeneratePage-quote > span:last-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.GeneratePage-quote strong {
  color: #465749;
  font-size: 9px;
  font-weight: 700;
}

.GeneratePage-quote small {
  color: #89938b;
  font-size: 8px;
}

.GeneratePage-submit {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  width: 100%;
  color: #fff;
  background: var(--canvas-ink, #171a17);
  border: 1px solid var(--canvas-ink, #171a17);
  border-radius: 8px;
  font-size: 11px;
  font-weight: 720;
  transition: color 160ms ease, background 160ms ease, border-color 160ms ease, transform 160ms ease;
}

.GeneratePage-submit:hover:not(:disabled) {
  color: var(--canvas-ink, #171a17);
  background: var(--canvas-green-soft, #e3f3cb);
  border-color: var(--canvas-green, #b9df8a);
  transform: translateY(-1px);
}

.GeneratePage-spin {
  animation: GeneratePage-spin 0.9s linear infinite;
}

.GeneratePage-results {
  display: flex;
  height: clamp(560px, calc(100vh - 104px), 720px);
  min-height: 560px;
  max-height: 720px;
  flex-direction: column;
  padding: 18px;
  overflow: hidden;
}

.GeneratePage-results-header {
  display: flex;
  flex: 0 0 auto;
  min-height: 46px;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 17px;
  border-bottom: 1px solid #edf0ee;
}

.GeneratePage-result-actions {
  display: inline-flex;
  align-items: center;
  gap: 9px;
}

.GeneratePage-status {
  display: inline-flex;
  height: 24px;
  align-items: center;
  gap: 6px;
  padding: 0 9px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 700;
}

.GeneratePage-status i {
  width: 5px;
  height: 5px;
  background: currentColor;
  border-radius: 50%;
}

.GeneratePage-status.is-pending,
.GeneratePage-status.is-processing {
  color: #9a6a1e;
  background: #fff6df;
}

.GeneratePage-status.is-completed {
  color: #4c7a2f;
  background: #e9f5df;
}

.GeneratePage-status.is-failed {
  color: #b55249;
  background: #fbe9e6;
}

.GeneratePage-clear-button {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  color: #7c867e;
  background: #f5f7f5;
  border: 1px solid #e2e8e3;
  border-radius: 7px;
  font-size: 11px;
}

.GeneratePage-clear-button:hover {
  color: var(--canvas-ink, #171a17);
  background: #eef3ed;
}

.GeneratePage-current-result {
  display: flex;
  min-width: 0;
  min-height: 220px;
  flex: 0 0 auto;
  flex-direction: column;
  justify-content: center;
  overflow-y: auto;
  scrollbar-width: thin;
}

.GeneratePage-empty-state {
  display: flex;
  min-height: 220px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  text-align: center;
}

.GeneratePage-empty-mark,
.GeneratePage-processing-mark,
.GeneratePage-error-mark {
  display: grid;
  place-items: center;
  color: #739c52;
  background: #edf6e7;
  border-radius: 12px;
}

.GeneratePage-empty-mark {
  width: 58px;
  height: 58px;
  margin-bottom: 18px;
  font-size: 24px;
}

.GeneratePage-empty-state h3,
.GeneratePage-processing-state h3,
.GeneratePage-error-state h3 {
  margin: 0;
  color: var(--canvas-ink, #171a17);
  font-size: 15px;
  font-weight: 720;
}

.GeneratePage-empty-state p,
.GeneratePage-processing-state p,
.GeneratePage-error-state p {
  max-width: 360px;
  margin: 8px 0 0;
  color: var(--canvas-muted, #737b75);
  font-size: 11px;
  line-height: 1.55;
}

.GeneratePage-empty-state.is-completed .GeneratePage-empty-mark {
  color: #4e852e;
  background: #e9f5df;
}

.GeneratePage-processing-state {
  min-height: 220px;
  padding: 28px 8px 8px;
}

.GeneratePage-processing-copy {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  text-align: left;
}

.GeneratePage-processing-mark {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  font-size: 16px;
  animation: GeneratePage-pulse 1.5s ease-in-out infinite;
}

.GeneratePage-skeleton-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  width: 100%;
  max-width: 520px;
  margin: 24px auto 0;
}

.GeneratePage-skeleton-grid span {
  display: block;
  aspect-ratio: 4 / 3;
  background: linear-gradient(110deg, #eef2ee 20%, #f8faf8 38%, #eef2ee 56%);
  background-size: 220% 100%;
  border-radius: 10px;
  animation: GeneratePage-shimmer 1.45s linear infinite;
}

.GeneratePage-media-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding-top: 18px;
}

.GeneratePage-current-result .GeneratePage-media-grid {
  max-height: 320px;
  overflow-y: auto;
  padding-right: 2px;
  scrollbar-width: thin;
}

.GeneratePage-media-result {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  background: #f2f4f2;
  border-radius: 10px;
}

.GeneratePage-media-result img,
.GeneratePage-media-result video {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  background: #e9eeeb;
}

.GeneratePage-media-result.is-video video {
  aspect-ratio: 16 / 9;
  object-fit: contain;
  background: #151814;
}

.GeneratePage-media-result figcaption {
  display: flex;
  min-height: 38px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  color: #78837b;
  font-family: 'SFMono-Regular', Consolas, monospace;
  font-size: 9px;
}

.GeneratePage-media-result figcaption a {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #4c7535;
  font-family: inherit;
  font-size: 9px;
  text-decoration: none;
}

.GeneratePage-media-result figcaption a:hover {
  color: #263d1c;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.GeneratePage-error-state {
  display: flex;
  min-height: 220px;
  align-items: center;
  justify-content: center;
  gap: 13px;
  padding: 32px;
  text-align: left;
}

.GeneratePage-error-mark {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  color: #b65745;
  background: #fff0e8;
  font-size: 17px;
}

.GeneratePage-error-state button {
  flex: 0 0 auto;
  min-height: 34px;
  padding: 7px 11px;
  color: #3f6530;
  background: #eef7e7;
  border: 1px solid #cee4bd;
  border-radius: 7px;
  font-size: 10px;
  font-weight: 700;
}

.GeneratePage-error-state button:hover {
  background: #e2f1d7;
}

.GeneratePage-history {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid #edf0ee;
}

.GeneratePage-history-header {
  display: flex;
  flex: 0 0 auto;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
}

.GeneratePage-history-header h3 {
  margin: 0;
  color: var(--canvas-ink, #171a17);
  font-size: 12px;
  font-weight: 720;
  line-height: 1.3;
}

.GeneratePage-history-header p {
  margin: 3px 0 0;
  color: var(--canvas-muted, #737b75);
  font-size: 9px;
  line-height: 1.4;
}

.GeneratePage-history-count {
  flex: 0 0 auto;
  padding-top: 1px;
  color: #809083;
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

.GeneratePage-history-list {
  display: grid;
  min-height: 0;
  flex: 1 1 auto;
  gap: 7px;
  overflow-y: auto;
  padding: 1px 3px 2px 0;
  scrollbar-width: thin;
}

.GeneratePage-history-item {
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr);
  align-items: stretch;
  gap: 9px;
  min-width: 0;
  min-height: 70px;
  padding: 7px;
  background: #fbfcfb;
  border: 1px solid #e5ebe6;
  border-radius: 8px;
}

.GeneratePage-history-thumb {
  display: grid;
  width: 70px;
  height: 56px;
  place-items: center;
  overflow: hidden;
  color: #72965d;
  background: #edf4e9;
  border-radius: 6px;
  font-size: 15px;
}

.GeneratePage-history-thumb img,
.GeneratePage-history-thumb video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: #e9eeeb;
}

.GeneratePage-history-thumb.is-video video {
  object-fit: contain;
  background: #171b17;
}

.GeneratePage-history-thumb.is-audio {
  color: #a06a35;
  background: #fff2df;
}

.GeneratePage-history-thumb.is-empty {
  color: #8a958d;
  background: #f0f3f0;
}

.GeneratePage-history-item-body {
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: space-between;
  gap: 4px;
}

.GeneratePage-history-item-header,
.GeneratePage-history-item-footer {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.GeneratePage-history-item-header strong {
  min-width: 0;
  overflow: hidden;
  color: #36443a;
  font-size: 10px;
  font-weight: 720;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.GeneratePage-history-status {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
  font-size: 8px;
  font-weight: 700;
  white-space: nowrap;
}

.GeneratePage-history-status i {
  width: 4px;
  height: 4px;
  background: currentColor;
  border-radius: 50%;
}

.GeneratePage-history-status.is-processing {
  color: #9a6a1e;
}

.GeneratePage-history-status.is-completed {
  color: #4c7a2f;
}

.GeneratePage-history-status.is-failed {
  color: #b55249;
}

.GeneratePage-history-item-body p {
  display: -webkit-box;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: #69746c;
  font-size: 9px;
  line-height: 1.4;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.GeneratePage-history-item-footer {
  color: #8a958d;
  font-size: 8px;
  font-variant-numeric: tabular-nums;
}

.GeneratePage-history-item-footer span {
  color: #6e846a;
}

.GeneratePage-history-state {
  display: flex;
  min-height: 82px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 8px;
  color: #7e8980;
  font-size: 9px;
  text-align: center;
}

.GeneratePage-history-state > i {
  color: #779b5c;
  font-size: 13px;
}

.GeneratePage-history-state.is-error {
  color: #ad5b4c;
}

.GeneratePage-history-login,
.GeneratePage-history-retry {
  min-height: 26px;
  padding: 4px 8px;
  color: #3f6530;
  background: #eef7e7;
  border: 1px solid #cee4bd;
  border-radius: 6px;
  font-size: 9px;
  font-weight: 700;
}

.GeneratePage-history-login:hover,
.GeneratePage-history-retry:hover {
  background: #e2f1d7;
}

.GeneratePage-history-inline-error {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 6px;
  color: #ad5b4c;
  font-size: 8px;
}

.GeneratePage-history-load-more {
  display: inline-flex;
  min-height: 28px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 7px;
  color: #5e7c52;
  background: #f5f8f3;
  border: 1px solid #dce9d5;
  border-radius: 7px;
  font-size: 9px;
  font-weight: 700;
}

.GeneratePage-history-load-more:hover:not(:disabled) {
  color: #36512d;
  background: #edf6e8;
  border-color: #c7dbbd;
}

.GeneratePage-history-load-more:disabled {
  cursor: wait;
  opacity: 0.6;
}

.GeneratePage-current-result::-webkit-scrollbar,
.GeneratePage-current-result .GeneratePage-media-grid::-webkit-scrollbar,
.GeneratePage-history-list::-webkit-scrollbar {
  width: 7px;
}

.GeneratePage-current-result::-webkit-scrollbar-thumb,
.GeneratePage-current-result .GeneratePage-media-grid::-webkit-scrollbar-thumb,
.GeneratePage-history-list::-webkit-scrollbar-thumb {
  background: #cbd8c9;
  border-radius: 999px;
}

.GeneratePage-current-result::-webkit-scrollbar-track,
.GeneratePage-current-result .GeneratePage-media-grid::-webkit-scrollbar-track,
.GeneratePage-history-list::-webkit-scrollbar-track {
  background: transparent;
}

@keyframes GeneratePage-pulse {
  50% { transform: scale(0.92); opacity: 0.65; }
}

@keyframes GeneratePage-shimmer {
  to { background-position: -220% 0; }
}

@keyframes GeneratePage-spin {
  to { transform: rotate(360deg); }
}

@keyframes GeneratePage-menu-enter {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

