  border: 1px solid var(--canvas-line);
}

.ModelSelectionModal-card:focus-visible {
  outline-color: var(--canvas-green-strong);
}

.ModelSelectionModal-hint i {
  color: var(--canvas-green-strong);
}

.DrawingModal-tool-btn {
  border: 1px solid var(--canvas-line);
}

.DrawingModal-tool-btn:hover,
.DrawingModal-tool-btn-active {
  color: var(--canvas-ink);
  background: var(--canvas-green-soft);
  border-color: var(--canvas-green);
}

.DrawingModal-slider::-webkit-slider-thumb,
.DrawingModal-slider::-moz-range-thumb {
  background: var(--canvas-ink);
}

.DrawingModal-preset-color-active {
  border-color: var(--canvas-green-strong) !important;
  box-shadow: 0 0 0 3px rgba(185, 223, 138, 0.28);
}

.DrawingModal-text-input {
  border-color: var(--canvas-green-strong);
  box-shadow: 0 6px 18px rgba(65, 85, 50, 0.12);
}

.DrawingModal-btn-save {
  color: #fff;
  background: var(--canvas-ink);
  box-shadow: none;
}

.DrawingModal-btn-save:hover {
  color: var(--canvas-ink);
  background: var(--canvas-green-soft);
  box-shadow: none;
}

.Toastify__toast {
  color: var(--canvas-ink);
  background: #fff;
  border: 1px solid var(--canvas-line);
  border-radius: 10px;
  box-shadow: var(--canvas-shadow);
  font-size: 13px;
}

.Toastify__progress-bar--success {
  background: var(--canvas-green-strong);
}

@media (max-width: 900px) {
  .canvas-login-page {
    display: flex;
    min-height: 100vh;
    padding: 44px 18px;
    background: var(--canvas-paper);
  }

  .canvas-login-intro {
    min-height: auto;
    padding: 0;
  }

  .canvas-login-intro h1 {
    font-size: clamp(30px, 9vw, 42px);
  }

  .canvas-login-intro > p {
    display: block;
  }

  .canvas-login-proof {
    display: none;
  }

  .canvas-login-panel {
    min-height: auto;
    padding: 24px;
    box-shadow: var(--canvas-shadow);
  }
}

@media (max-width: 720px) {
  .canvas-workspace-header {
    min-height: 56px;
    padding: 0 14px;
  }

  .InspirationCanvas-header-inner {
    min-height: 230px;
    padding: 36px 0 20px;
  }

  .InspirationCanvas-brand-logo {
    width: 320px;
    max-width: 82vw;
    margin-bottom: 16px;
  }

  .InspirationCanvas-main {
    padding: 18px 14px 60px;
  }

  .InspirationCanvas-section-header p {
    display: none;
  }

  .InspirationCanvas-masonry-container,
  .InspirationCanvas-masonry-column {
    gap: 7px;
  }

  .CanvasEditor-toolbar {
    padding: 0 10px;
  }

  .CanvasEditor-toolbar-left,
  .CanvasEditor-toolbar-right {
    gap: 7px;
  }

  .CanvasEditor-title {
    max-width: 140px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}
