.PromptInputNode-super-button:hover {
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}

/* 第一个按钮悬停 - 向外上方移动 */
.PromptInputNode-super-button:nth-child(1):hover {
  transform: translate(8px, -10px);
}

/* 第二个按钮悬停 - 向外右移动 */
.PromptInputNode-super-button:nth-child(2):hover {
