}

/* 第一个按钮按下 */
.PromptInputNode-super-button:nth-child(1):active {
  transform: translate(4px, -5px);
}

/* 第二个按钮按下 */
.PromptInputNode-super-button:nth-child(2):active {
  transform: translate(6px, -50%);
}

/* 第三个按钮按下 */
.PromptInputNode-super-button:nth-child(3):active {
  transform: translate(4px, 5px);
}

/* 禁用状态 */
.PromptInputNode-super-button:disabled {
  opacity: 0.65;
  cursor: not-allowed;
  pointer-events: none;
}

/* 图片按钮 - Bootstrap Primary 蓝色 */
.PromptInputNode-super-button-image {
  color: #0d6efd;
  border-color: #0d6efd;
}

.PromptInputNode-super-button-image:hover {
  background: #0d6efd;
  color: white;
  border-color: #0d6efd;
}

.PromptInputNode-super-button-image:active {
  background: #0b5ed7;
  border-color: #0b5ed7;
}

/* 视频按钮 - Bootstrap Success 绿色 */
.PromptInputNode-super-button-video {
  color: #198754;
  border-color: #198754;
}

.PromptInputNode-super-button-video:hover {
  background: #198754;
  color: white;
  border-color: #198754;
}

.PromptInputNode-super-button-video:active {
  background: #157347;
  border-color: #157347;
}

/* 音频按钮 - Bootstrap Warning 橙色 */
.PromptInputNode-super-button-audio {
  color: #fd7e14;
  border-color: #fd7e14;
}

.PromptInputNode-super-button-audio:hover {
  background: #fd7e14;
  color: white;
  border-color: #fd7e14;
}

.PromptInputNode-super-button-audio:active {
  background: #e66a00;
  border-color: #e66a00;
}

