@keyframes PromptInputNode-buttonFadeIn {
  0% {
    opacity: 0;
    transform: scale(0.5);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

/* 第一个按钮的特殊动画 - 从内向外上展开 */
@keyframes PromptInputNode-button1FadeIn {
  0% {
    opacity: 0;
    left: 40px;
    top: 50px;
  }
  100% {
    opacity: 1;
    left: 20px;
    top: 0;
  }
}

/* 第二个按钮的特殊动画 - 从内向外右展开 */
@keyframes PromptInputNode-button2FadeIn {
  0% {
    opacity: 0;
    right: 40px;
  }
  100% {
    opacity: 1;
    right: 0;
  }
}

/* 第三个按钮的特殊动画 - 从内向外下展开 */
@keyframes PromptInputNode-button3FadeIn {
  0% {
    opacity: 0;
    left: 40px;
    bottom: 50px;
  }
  100% {
    opacity: 1;
    left: 20px;
    bottom: 0;
  }
}

