.react-flow__node.selected .PromptInputNode-super-button:nth-child(1) {
  animation: PromptInputNode-button1FadeIn 0.3s ease-out;
}

.react-flow__node.selected .PromptInputNode-super-button:nth-child(2) {
  animation: PromptInputNode-button2FadeIn 0.3s ease-out;
}

.react-flow__node.selected .PromptInputNode-super-button:nth-child(3) {
  animation: PromptInputNode-button3FadeIn 0.3s ease-out;
}

