.PromptInputNode-super-button:nth-child(1) {
  transition-delay: 0.05s;
}

.PromptInputNode-super-button:nth-child(2) {
  transition-delay: 0.1s;
}

.PromptInputNode-super-button:nth-child(3) {
  transition-delay: 0.15s;
}

