___CSS_LOADER_EXPORT___.push([module.id, `/* CanvasEditor 样式 */
.CanvasEditor-container {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  background: #d8d6ce;
}

.CanvasEditor-toolbar {
  min-height: 58px;
  background: #11120f;
  border-bottom: 1px solid #35382f;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1rem;
  z-index: 1000;
}

.CanvasEditor-toolbar-left {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.CanvasEditor-back-button {
  padding: 0.5rem 1rem;
  color: #d9dccf;
  background: transparent;
  border: 1px solid #45483f;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: background 0.2s;
}

.CanvasEditor-back-button:hover {
  color: #11120f;
  background: #d8ff45;
  border-color: #d8ff45;
}

.CanvasEditor-title-wrapper {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.CanvasEditor-title {
  margin: 0;
  font-size: 1.1rem;
  color: #f2efe6;
  font-family: Georgia, 'Songti SC', serif;
  font-weight: 400;
}

.CanvasEditor-title-input {
  margin: 0;
  font-size: 1.1rem;
  color: #333;
  padding: 0.25rem 0.5rem;
  border: 2px solid #667eea;
  border-radius: 4px;
  outline: none;
  min-width: 200px;
}

.CanvasEditor-edit-button {
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0.25rem;
  color: #666;
  transition: color 0.2s;
  font-size: 16px;
}

.CanvasEditor-edit-button:hover {
  color: #667eea;
}

.CanvasEditor-toolbar-right {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.CanvasEditor-saving {
  color: #999;
  font-size: 0.9rem;
}

.CanvasEditor-save-button {
  padding: 0.5rem 1rem;
  background: #d8ff45;
  color: #11120f;
  border: none;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: background 0.2s;
}

.CanvasEditor-save-button:hover {
  background: #e5ff80;
}

.CanvasEditor-save-button:disabled {
  background: #ccc;
  cursor: not-allowed;
  opacity: 0.6;
}

.CanvasEditor-share-button {
  padding: 0.5rem;
  background: transparent;
  color: #94a3b8;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
}

.CanvasEditor-share-button:hover {
  background: rgba(148, 163, 184, 0.1);
  color: #64748b;
}

.CanvasEditor-export-button {
  padding: 0.5rem;
  background: transparent;
  color: #94a3b8;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  position: relative;
}

.CanvasEditor-export-button:hover {
  background: rgba(148, 163, 184, 0.1);
  color: #64748b;
}

.CanvasEditor-export-button:disabled {
  cursor: not-allowed;
  color: #cbd5f5;
  background: rgba(148, 163, 184, 0.12);
}

.CanvasEditor-export-spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(148, 163, 184, 0.4);
  border-top-color: #64748b;
  border-radius: 50%;
  animation: CanvasEditor-spin 0.8s linear infinite;
}

.CanvasEditor-exporting {
  color: #666;
  font-size: 0.9rem;
}

.CanvasEditor-export-button:disabled .CanvasEditor-export-spinner {
  border-top-color: #94a3b8;
}

.CanvasEditor-login-button {
  padding: 0.5rem 1.5rem;
  background: #d8ff45;
  color: #11120f;
  border: none;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: 500;
  transition: all 0.2s;
  box-shadow: 0 2px 4px rgba(102, 126, 234, 0.2);
}

.CanvasEditor-login-button:hover {
  background: #e5ff80;
  box-shadow: 0 4px 8px rgba(102, 126, 234, 0.3);
  transform: translateY(-1px);
}

.CanvasEditor-canvas {
  flex: 1;
  position: relative;
  overflow: hidden;
  min-height: 0;
}

.CanvasEditor-loading,
.CanvasEditor-error {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #f5f5f5;
  gap: 1rem;
}

.CanvasEditor-error-message {
  color: #e53e3e;
  font-size: 1.2rem;
}

.CanvasEditor-error-button {
  padding: 0.75rem 1.5rem;
  background: #667eea;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 1rem;
  transition: background 0.2s;
}

.CanvasEditor-error-button:hover {
  background: #5568d3;
}

/* 只读徽章 */
.CanvasEditor-readonly-badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: #fef3c7;
  color: #92400e;
  border-radius: 12px;
  font-size: 0.85rem;
  font-weight: 500;
}

/* 复制按钮 */
.CanvasEditor-clone-button {
  padding: 0.5rem 1rem;
  background: #10b981;
  color: white;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: background 0.2s;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.CanvasEditor-clone-button:hover {
  background: #059669;
}

.CanvasEditor-clone-button:disabled {
  background: #ccc;
  cursor: not-allowed;
  opacity: 0.6;
}

/* 会员升级弹窗样式 */
.CanvasEditor-dialog-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10000;
  animation: CanvasEditor-fadeIn 0.2s ease-out;
}

.CanvasEditor-dialog {
  background: white;
  border-radius: 24px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.3);
  max-width: 480px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
  animation: CanvasEditor-slideUp 0.3s ease-out;
}

.CanvasEditor-dialog-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #1a202c;
  margin: 0 0 0.75rem 0;
  text-align: center;
  line-height: 1.3;
}

.CanvasEditor-dialog-actions {
  display: flex;
  gap: 1rem;
  margin-top: 1.5rem;
  justify-content: center;
}

.CanvasEditor-dialog-button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.85rem 1.75rem;
  border: none;
  border-radius: 14px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  min-width: 120px;
}

.CanvasEditor-dialog-button:hover {
  transform: translateY(-1px);
}

.CanvasEditor-dialog-button-cancel {
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba(148, 163, 184, 0.35);
  color: #475569;
}

.CanvasEditor-dialog-button-cancel:hover {
  background: rgba(241, 245, 249, 0.96);
  border-color: rgba(99, 102, 241, 0.45);
}

.CanvasEditor-upgrade-overlay {
  padding: 2rem;
}

.CanvasEditor-upgrade-dialog {
  position: relative;
  overflow: hidden;
  max-width: 540px;
  padding: 3rem 2.75rem 2.5rem;
  text-align: center;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96) 0%, #ffffff 65%, rgba(245, 247, 250, 0.98) 100%);
  border: 1px solid rgba(255, 255, 255, 0.7);
  box-shadow: 0 32px 80px rgba(15, 23, 42, 0.35);
  animation: CanvasEditor-upgrade-pop 280ms ease-out;
}

.CanvasEditor-upgrade-dialog::before,
.CanvasEditor-upgrade-dialog::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(0px);
}

.CanvasEditor-upgrade-dialog::before {
  width: 320px;
  height: 320px;
  background: radial-gradient(circle, rgba(254, 215, 170, 0.55) 0%, rgba(255, 255, 255, 0) 65%);
  top: -140px;
  right: -120px;
}

.CanvasEditor-upgrade-dialog::after {
  width: 260px;
  height: 260px;
  background: radial-gradient(circle, rgba(127, 61, 255, 0.35) 0%, rgba(255, 255, 255, 0) 75%);
  bottom: -110px;
  left: -90px;
}

.CanvasEditor-upgrade-icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  margin: 0 auto 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #fed7aa 0%, #f97316 100%);
  color: #9a3412;
  box-shadow: 0 10px 40px rgba(249, 115, 22, 0.25);
  position: relative;
  z-index: 1;
}

.CanvasEditor-upgrade-icon svg {
  width: 36px;
  height: 36px;
}

.CanvasEditor-upgrade-title {
  margin-bottom: 0.75rem;
  position: relative;
  z-index: 1;
}

.CanvasEditor-upgrade-message {
  font-size: 1rem;
  color: #3c4559;
  line-height: 1.65;
  margin: 0 auto 1.85rem auto;
  max-width: 420px;
  padding: 0.75rem 1rem;
  background: rgba(236, 244, 255, 0.65);
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 12px;
  position: relative;
  z-index: 1;
}

.CanvasEditor-upgrade-benefits {
  list-style: none;
  padding: 0;
  margin: 0 0 1.75rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  color: #2d3748;
  font-size: 0.95rem;
  position: relative;
  z-index: 1;
}

.CanvasEditor-upgrade-benefits li {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0.5rem;
  text-align: left;
  padding: 0.65rem 0.9rem;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.65);
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.08);
}

.CanvasEditor-upgrade-benefits li::before {
  content: '';
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #fcd34d 0%, #f97316 60%, #c026d3 100%);
  flex-shrink: 0;
}

.CanvasEditor-upgrade-actions {
  margin-top: 1rem;
  justify-content: center;
  position: relative;
  z-index: 1;
}

.CanvasEditor-upgrade-button {
  background: linear-gradient(135deg, #7f3dff 0%, #d53f8c 100%);
  color: #ffffff;
  box-shadow: 0 10px 30px rgba(127, 61, 255, 0.35);
  min-width: 150px;
}

.CanvasEditor-upgrade-button:hover {
  background: linear-gradient(135deg, #6b2bd3 0%, #b83280 100%);
  transform: translateY(-1px);
}

.CanvasEditor-upgrade-actions .CanvasEditor-dialog-button-cancel {
  min-width: 120px;
}

/* 动画效果 */
@keyframes CanvasEditor-fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes CanvasEditor-slideUp {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes CanvasEditor-upgrade-pop {
  0% {
    opacity: 0;
    transform: translateY(24px) scale(0.96);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes CanvasEditor-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* 响应式设计 */
@media (max-width: 768px) {
  .CanvasEditor-upgrade-overlay {
    padding: 1.5rem;
  }

  .CanvasEditor-upgrade-dialog {
    padding: 2.5rem 1.5rem 2rem;
  }

  .CanvasEditor-upgrade-message {
    padding: 0.65rem 0.75rem;
  }

  .CanvasEditor-upgrade-benefits li {
    padding: 0.55rem 0.75rem;
  }
}

/* 公开项目提示弹窗 */
.CanvasEditor-public-dialog {
  max-width: 420px;
  padding: 2rem 2rem 1.5rem;
  text-align: center;
}

.CanvasEditor-public-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%);
  color: #1e40af;
}

.CanvasEditor-public-message {
  font-size: 0.95rem;
  color: #475569;
  line-height: 1.6;
  margin: 0 0 1.5rem 0;
}

.CanvasEditor-dialog-button-confirm {
  background: #10b981;
  color: white;
}

.CanvasEditor-dialog-button-confirm:hover {
  background: #059669;
}

/* 图片转存提示弹窗 */
.CanvasEditor-transfer-dialog {
  max-width: 500px;
  padding: 2rem 2rem 1.5rem;
  text-align: center;
}

.CanvasEditor-transfer-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
  color: #d97706;
}

.CanvasEditor-transfer-message {
  font-size: 0.95rem;
  color: #475569;
  line-height: 1.6;
  margin: 0 0 1.5rem 0;
}

.CanvasEditor-transfer-details {
  margin: 1rem 0 1.5rem 0;
  padding: 1rem;
  background: #f8fafc;
  border-radius: 8px;
  text-align: left;
}

.CanvasEditor-transfer-tip {
  font-size: 0.875rem;
  color: #64748b;
  margin-bottom: 1rem;
  padding: 0.75rem;
  background: white;
  border-left: 3px solid #f59e0b;
  border-radius: 4px;
}

.CanvasEditor-transfer-list {
  margin-top: 1rem;
}

.CanvasEditor-transfer-list-title {
  font-weight: 600;
  font-size: 0.875rem;
  color: #334155;
  margin-bottom: 0.5rem;
}

.CanvasEditor-transfer-item {
  font-size: 0.85rem;
  color: #64748b;
  padding: 0.5rem;
  background: white;
  border-radius: 4px;
  margin-bottom: 0.25rem;
}

/* 帮助按钮样式 */
.CanvasEditor-help-button {
  padding: 0.5rem;
  background: transparent;
  border: 1px solid #ddd;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  color: #667eea;
}

.CanvasEditor-help-button:hover {
  background: #f0f4ff;
  border-color: #667eea;
  transform: translateY(-1px);
}

.CanvasEditor-help-button svg {
  display: block;
}
