 background: #d8d6ce;\n}\n\n.CanvasEditor-toolbar {\n  min-height: 58px;\n  background: #11120f;\n  border-bottom: 1px solid #35382f;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 1rem;\n  z-index: 1000;\n}\n\n.CanvasEditor-toolbar-left {\n  display: flex;\n  align-items: center;\n  gap: 1rem;\n}\n\n.CanvasEditor-back-button {\n  padding: 0.5rem 1rem;\n  color: #d9dccf;\n  background: transparent;\n  border: 1px solid #45483f;\n  border-radius: 999px;\n  cursor: pointer;\n  font-size: 0.9rem;\n  transition: background 0.2s;\n}\n\n.CanvasEditor-back-button:hover {\n  color: #11120f;\n  background: #d8ff45;\n  border-color: #d8ff45;\n}\n\n.CanvasEditor-title-wrapper {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.CanvasEditor-title {\n  margin: 0;\n  font-size: 1.1rem;\n  color: #f2efe6;\n  font-family: Georgia, 'Songti SC', serif;\n  font-weight: 400;\n}\n\n.CanvasEditor-title-input {\n  margin: 0;\n  font-size: 1.1rem;\n  color: #333;\n  padding: 0.25rem 0.5rem;\n  border: 2px solid #667eea;\n  border-radius: 4px;\n  outline: none;\n  min-width: 200px;\n}\n\n.CanvasEditor-edit-button {\n  background: transparent;\n  border: none;\n  cursor: pointer;\n  padding: 0.25rem;\n  color: #666;\n  transition: color 0.2s;\n  font-size: 16px;\n}\n\n.CanvasEditor-edit-button:hover {\n  color: #667eea;\n}\n\n.CanvasEditor-toolbar-right {\n  display: flex;\n  align-items: center;\n  gap: 1rem;\n}\n\n.CanvasEditor-saving {\n  color: #999;\n  font-size: 0.9rem;\n}\n\n.CanvasEditor-save-button {\n  padding: 0.5rem 1rem;\n  background: #d8ff45;\n  color: #11120f;\n  border: none;\n  border-radius: 999px;\n  cursor: pointer;\n  font-size: 0.9rem;\n  transition: background 0.2s;\n}\n\n.CanvasEditor-save-button:hover {\n  background: #e5ff80;\n}\n\n.CanvasEditor-save-button:disabled {\n  background: #ccc;\n  cursor: not-allowed;\n  opacity: 0.6;\n}\n\n.CanvasEditor-share-button {\n  padding: 0.5rem;\n  background: transparent;\n  color: #94a3b8;\n  border: none;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 36px;\n  height: 36px;\n}\n\n.CanvasEditor-share-button:hover {\n  background: rgba(148, 163, 184, 0.1);\n  color: #64748b;\n}\n\n.CanvasEditor-export-button {\n  padding: 0.5rem;\n  background: transparent;\n  color: #94a3b8;\n  border: none;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 36px;\n  height: 36px;\n  position: relative;\n}\n\n.CanvasEditor-export-button:hover {\n  background: rgba(148, 163, 184, 0.1);\n  color: #64748b;\n}\n\n.CanvasEditor-export-button:disabled {\n  cursor: not-allowed;\n  color: #cbd5f5;\n  background: rgba(148, 163, 184, 0.12);\n}\n\n.CanvasEditor-export-spinner {\n  width: 16px;\n  height: 16px;\n  border: 2px solid rgba(148, 163, 184, 0.4);\n  border-top-color: #64748b;\n  border-radius: 50%;\n  animation: CanvasEditor-spin 0.8s linear infinite;\n}\n\n.CanvasEditor-exporting {\n  color: #666;\n  font-size: 0.9rem;\n}\n\n.CanvasEditor-export-button:disabled .CanvasEditor-export-spinner {\n  border-top-color: #94a3b8;\n}\n\n.CanvasEditor-login-button {\n  padding: 0.5rem 1.5rem;\n  background: #d8ff45;\n  color: #11120f;\n  border: none;\n  border-radius: 999px;\n  cursor: pointer;\n  font-size: 0.9rem;\n  font-weight: 500;\n  transition: all 0.2s;\n  box-shadow: 0 2px 4px rgba(102, 126, 234, 0.2);\n}\n\n.CanvasEditor-login-button:hover {\n  background: #e5ff80;\n  box-shadow: 0 4px 8px rgba(102, 126, 234, 0.3);\n  transform: translateY(-1px);\n}\n\n.CanvasEditor-canvas {\n  flex: 1;\n  position: relative;\n  overflow: hidden;\n  min-height: 0;\n}\n\n.CanvasEditor-loading,\n.CanvasEditor-error {\n  position: fixed;\n  inset: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  background: #f5f5f5;\n