@keyframes VideoFaceSwapNode-labelFadeIn {
  0% {
    opacity: 0;
    transform: translateY(-50%) translateX(-10px);
  }
  100% {
    opacity: 1;
    transform: translateY(-50%) translateX(-2px);
  }
}

.VideoFaceSwapNode-handle:hover .VideoFaceSwapNode-handle-label,
.react-flow__node.selected .VideoFaceSwapNode-handle .VideoFaceSwapNode-handle-label {
  animation: VideoFaceSwapNode-labelFadeIn 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* 可点击的 Handle 标签 */
.VideoFaceSwapNode-handle-label-clickable {
  pointer-events: auto;  /* 改为可交互 */
  cursor: pointer;       /* 显示手型光标 */
  user-select: none;     /* 禁止文本选择 */
}

/* 可点击标签的悬停效果 */
.VideoFaceSwapNode-handle-label-clickable:hover {
  transform: translateY(-50%) translateX(-4px) scale(1.05);
  box-shadow: 0 8px 24px rgba(99, 102, 241, 0.45);
}

.VideoFaceSwapNode-handle-video .VideoFaceSwapNode-handle-label-clickable:hover {
  box-shadow: 0 8px 24px rgba(59, 130, 246, 0.45);
}

.VideoFaceSwapNode-handle-face .VideoFaceSwapNode-handle-label-clickable:hover {
  box-shadow: 0 8px 24px rgba(72, 187, 120, 0.45);
}

/* 可点击标签的按下效果 */
.VideoFaceSwapNode-handle-label-clickable:active {
  transform: translateY(-50%) translateX(-2px) scale(0.98);
}

/* 添加点击提示图标 */
.VideoFaceSwapNode-handle-label-clickable::after {
  content: ' +';
  font-weight: 700;
  margin-left: 4px;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.VideoFaceSwapNode-handle-label-clickable:hover::after {
  opacity: 1;
}

/* 标题 */
.VideoFaceSwapNode-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  text-align: center;
  color: #fff;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
  letter-spacing: 0.5px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.VideoFaceSwapNode-title::before {
  content: '🎭';
  font-size: 20px;
}

/* 包装器 */
.VideoFaceSwapNode-wrapper {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* 字段 */
.VideoFaceSwapNode-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: rgba(255, 255, 255, 0.08);
  padding: 12px;
  border-radius: 12px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  transition: all 0.3s ease;
}

.VideoFaceSwapNode-field:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.25);
}

.VideoFaceSwapNode-label {
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 255, 255, 1);
  display: flex;
  align-items: center;
  gap: 6px;
}

.VideoFaceSwapNode-label::before {
  content: '';
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
}

