  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.3s ease;
}

.VideoFaceSwapNode-image-preview:hover .VideoFaceSwapNode-preview-img {
  transform: scale(1.05);
}

